.shop-menu ul li:last-child {
    padding-right: 0;
}

.shop-menu ul li a {
    color: #696763;
    font-family: "Roboto", sans-serif;
    font-size: 14px;
    font-weight: 300;
    padding: 0;
    padding-right: 0;
    margin-top: 10px;
}

.shop-menu ul li a i {
    margin-right: 3px;
}

.shop-menu ul li a:hover {
    color: #d70018;
}

.header-bottom {
    padding-bottom: 11px;
    padding-top: 20px;
    z-index: 9999;
    background: #d70018;
}

.navbar-collapse.collapse {
    padding-left: 0;
}

.mainmenu ul li {
    padding-right: 15px;
    padding-left: 15px;
}

.mainmenu ul li:first-child {
    padding-left: 0px;
}

.mainmenu ul li a {
    color: #fff;
    font-family: "Roboto", sans-serif;
    font-size: 17px;
    font-weight: bold;
    padding: 0;
    padding-bottom: 10px;
}
.menu-item:hover > .cate_sub {
    display: block;
    background: #ff2828;
}
.mainmenu ul li a:hover,
.mainmenu ul li a.active,
.shop-menu ul li a.active {
    background: none;
    color: #fdb45e;
}
/* General menu styling */
.menu-item {
    position: relative;
    /* Needed for submenu positioning */
}

.cate_sub {
    list-style: none;
    padding: 0;
    margin: 0;
    display: none;
    /* Hidden by default */
    position: absolute;
    top: 0;
    left: 100%;
    /* Position the submenu to the left */
    background-color: #fff;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    z-index: 1000;
    min-width: 200px;
    /* Set a minimum width for the submenu */
}

.cate_sub li {
    position: relative;
}

.cate_sub li a {
    display: block;
    padding: 10px 15px;
    text-decoration: none;
    color: #333;
}

.cate_sub li a:hover {
    background-color: #f0f0f0;
    /* Highlight on hover */
}

/* Show submenu on hover */
.menu-item:hover > .cate_sub {
    display: block;
}
.search_box input {
    background: #ffffff;
    border: medium none;
    color: #000;
    font-family: "roboto";
    font-size: 15px;
    font-weight: 300;
    float: left;
    height: 35px;
    outline: medium none;
    padding-left: 10px;
    width: 155px;
    background-image: none;
    background-repeat: no-repeat;
    background-position: 130px;
}

/*  Dropdown menu*/

.navbar-header .navbar-toggle .icon-bar {
    background-color: #fff;
}

.nav.navbar-nav > li:hover > ul.sub-menu {
    display: block;
    -webkit-animation: fadeInUp 400ms;
    -moz-animation: fadeInUp 400ms;
    -ms-animation: fadeInUp 400ms;
    -o-animation: fadeInUp 400ms;
    animation: fadeInUp 400ms;
}

ul.sub-menu {
    position: absolute;
    top: 30px;
    left: 0;
    background: #f16a6a;
    list-style: none;
    padding: 0;
    margin: 0;
    width: 220px;
    -webkit-box-shadow: 0 3px 3px rgba(0, 0, 0, 0.1);
    box-shadow: 0 3px 3px rgba(0, 0, 0, 0.1);
    display: none;
    z-index: 999;
}

.dropdown ul.sub-menu li .active {
    color: #fdb45e;
    padding-left: 0;
}

.navbar-nav li ul.sub-menu li {
    padding: 10px 20px 0;
}

.navbar-nav li ul.sub-menu li:last-child {
    padding-bottom: 3px;
}

.navbar-nav li ul.sub-menu li a {
    color: #fff;
}

.navbar-nav li ul.sub-menu li a:hover {
    color: #fdb45e;
}

.fa-angle-down {
    padding-left: 5px;
}

@-webkit-keyframes fadeInUp {
    0% {
        opacity: 0;
        -webkit-transform: translateY(20px);
        transform: translateY(20px);
    }

    100% {
        opacity: 1;
        -webkit-transform: translateY(0);
        transform: translateY(0);
    }
}

