:root {
  --shopw-red: #d50018;
  --shopw-red-dark: #b30014;
  --shopw-blue: #0f6bff;
  --shopw-blue-soft: #19c3ff;
  --shopw-yellow: #ffcc3d;
  --shopw-orange: #ff7a00;
  --shopw-gray-100: #f5f6f9;
  --shopw-gray-200: #e5e7eb;
  --shopw-gray-900: #0f172a;
  --shopw-shadow: 0 12px 26px rgba(17, 24, 39, 0.16);
  --shopw-shadow-sm: 0 8px 16px rgba(15, 23, 42, 0.12);
  --shopw-radius: 4px;
  --shopw-hero-side: 230px;
  --shopw-hero-ratio: 20 / 10;
}

body {
  font-family: "Be Vietnam Pro", "Segoe UI", sans-serif;
  background-color: var(--shopw-gray-100);
  color: var(--shopw-gray-900);
}

body.g-home {
  background: #f0f7ff;
}

body.g-home .container {
  max-width: 1240px !important;
  width: 100%;
}

#header {
  position: relative;
  z-index: 10000;
}

.shopw-auth-menu {
  position: relative;
}

.shopw-account-menu {
  position: relative;
  display: block;
  width: 100%;
}

.shopw-account-menu > summary {
  list-style: none;
}

.shopw-account-menu > summary::-webkit-details-marker {
  display: none;
}

.shopw-account-summary {
  color: #fff;
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 54px;
  padding: 9px 12px;
  min-width: 0;
  width: min(212px, 100%);
  max-width: 212px;
  border-radius: 14px;
  background: rgba(124, 0, 15, 0.24);
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: pointer;
  transition: background 0.2s ease, transform 0.2s ease;
}

.shopw-account-summary--avatar-only {
  justify-content: center;
  gap: 0;
  width: 100%;
  max-width: none;
  min-height: 46px;
  padding: 0;
}

.shopw-account-summary:hover {
  background: rgba(255, 255, 255, 0.12);
  transform: translateY(-1px);
}

.shopw-account-summary.is-current,
.shopw-account-menu[open] .shopw-account-summary {
  background: rgba(124, 0, 15, 0.42);
  border-color: rgba(255, 255, 255, 0.22);
}

.shopw-account-avatar {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
  flex: 0 0 auto;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.shopw-account-summary--avatar-only .shopw-account-avatar {
  margin: 0 auto;
}

.shopw-account-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.shopw-account-summary-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
  flex: 1 1 auto;
}

.shopw-account-summary-copy strong,
.shopw-account-summary-copy small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shopw-account-summary-copy strong {
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
}

.shopw-account-summary-copy small {
  color: rgba(255, 255, 255, 0.74);
  font-size: 11px;
  font-weight: 600;
}

.shopw-account-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 10px);
  width: 280px;
  padding: 14px;
  border-radius: 18px;
  background: #fff;
  border: 1px solid rgba(226, 232, 240, 0.96);
  box-shadow: 0 26px 44px rgba(15, 23, 42, 0.18);
  z-index: 9999;
}

.shopw-account-dropdown-head {
  display: grid;
  gap: 4px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.shopw-account-dropdown-kicker {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.shopw-account-dropdown-head strong {
  color: #0f172a;
  font-size: 16px;
  font-weight: 800;
}

.shopw-account-dropdown-head small {
  color: #64748b;
  font-size: 12px;
  line-height: 1.5;
}

.shopw-account-dropdown-links {
  display: grid;
  gap: 8px;
  padding-top: 12px;
}

.shopw-account-dropdown-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 14px;
  border-radius: 12px;
  color: #1e293b;
  text-decoration: none;
  background: #f8fafc;
  border: 1px solid rgba(226, 232, 240, 0.9);
  font-size: 13px;
  font-weight: 700;
}

.shopw-account-dropdown-link:hover {
  color: var(--shopw-blue);
  border-color: rgba(15, 107, 255, 0.18);
}

.shopw-account-dropdown-link.is-danger:hover {
  color: var(--shopw-red);
  border-color: rgba(213, 0, 24, 0.2);
}

.g-login-checkout .shopw-auth-identity {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  align-items: center;
}

.g-login-checkout .shopw-auth-identity-avatar {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(15, 107, 255, 0.14), rgba(25, 195, 255, 0.18));
  color: var(--shopw-blue);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 800;
}

.g-login-checkout .shopw-auth-identity-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.g-login-checkout .shopw-auth-identity-copy {
  display: grid;
  gap: 2px;
}

.g-login-checkout .shopw-auth-identity-kicker {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.g-login-checkout .shopw-auth-identity-copy small {
  color: #64748b;
  font-size: 12px;
}

.g-login-checkout .shopw-auth-switcher {
  display: grid;
  gap: 16px;
  padding: 18px 20px;
  border-radius: 20px;
  background: #fff;
  border: 1px solid rgba(203, 213, 225, 0.88);
  box-shadow: 0 18px 34px rgba(15, 23, 42, 0.06);
}

.g-login-checkout .shopw-auth-switcher > summary {
  list-style: none;
  cursor: pointer;
  color: #0f172a;
  font-size: 14px;
  font-weight: 800;
}

.g-login-checkout .shopw-auth-switcher > summary::-webkit-details-marker {
  display: none;
}

.g-login-checkout .shopw-auth-switcher > summary::after {
  content: "\f107";
  font-family: FontAwesome;
  margin-left: 10px;
  color: #64748b;
}

.g-login-checkout .shopw-auth-switcher[open] > summary::after {
  content: "\f106";
}

.g-login-checkout .shopw-auth-switcher .shopw-auth-layout {
  margin-top: 4px;
}

.g-checkout .shopw-checkout-account-card {
  display: grid;
  gap: 14px;
  margin-bottom: 18px;
  padding: 18px;
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(15, 107, 255, 0.05), rgba(25, 195, 255, 0.08));
  border: 1px solid rgba(148, 163, 184, 0.18);
}

.g-checkout .shopw-checkout-account-main {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  align-items: center;
}

.g-checkout .shopw-checkout-account-avatar {
  width: 54px;
  height: 54px;
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(15, 107, 255, 0.14), rgba(25, 195, 255, 0.18));
  color: var(--shopw-blue);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 800;
}

.g-checkout .shopw-checkout-account-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.g-checkout .shopw-checkout-account-copy {
  display: grid;
  gap: 2px;
}

.g-checkout .shopw-checkout-account-kicker {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.g-checkout .shopw-checkout-account-copy strong {
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

.g-checkout .shopw-checkout-account-copy small {
  color: #64748b;
  font-size: 12px;
}

.g-checkout .shopw-checkout-account-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

@media (max-width: 991px) {
  .shopw-account-dropdown {
    width: min(280px, calc(100vw - 36px));
  }

  .g-login-checkout .shopw-auth-identity,
  .g-checkout .shopw-checkout-account-main {
    grid-template-columns: 1fr;
    justify-items: start;
  }
}

:root {
  --shopw-hero-cycle: 4s;
  --shopw-flash-red: #d70018;
  --shopw-flash-red-dark: #af0013;
  --shopw-flash-card-shadow: 0 20px 40px rgba(124, 0, 15, 0.2);
}

.shopw-search {
  border-radius: 18px;
  overflow: visible;
  min-height: 52px;
  height: 52px;
}

.shopw-search input {
  padding: 11px 18px;
  font-size: 15px;
}

.shopw-search-btn {
  flex: 0 0 58px;
  width: 58px;
  min-width: 58px;
  max-width: 58px;
  height: 52px;
  background: linear-gradient(135deg, #2dd4bf 0%, #0d9488 100%);
  color: #fff;
  border-left: 1px solid rgba(255, 255, 255, 0.18);
}

.shopw-search-btn:hover {
  color: #fff;
}

.shopw-search-suggest {
  top: calc(100% + 10px);
  border-radius: 20px;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.shopw-search-suggest-panel {
  padding: 0;
  border-radius: 24px;
  border: 1px solid #cffafe;
  background: #fff;
  box-shadow: 0 20px 50px rgba(8, 145, 178, 0.15);
  overflow: hidden;
}

.shopw-search-suggest-layout {
  display: grid;
  grid-template-columns: minmax(220px, 268px) minmax(0, 1fr);
  min-width: 0;
}

.shopw-search-suggest-side {
  display: grid;
  align-content: start;
  gap: 16px;
  padding: 18px 16px;
  background:
    radial-gradient(circle at top right, rgba(207, 250, 254, 0.8), transparent 44%),
    linear-gradient(180deg, #f0fdfa 0%, #fff 100%);
  border-right: 1px solid #ccfbf1;
}

.shopw-search-suggest-main {
  display: grid;
  align-content: start;
  gap: 12px;
  min-width: 0;
  padding: 18px 18px 16px;
}

.shopw-search-suggest-group {
  display: grid;
  gap: 10px;
}

.shopw-search-suggest-group-title {
  color: #0d9488;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.shopw-search-suggest-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.shopw-search-suggest-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid #ccfbf1;
  border-radius: 999px;
  background: #fff;
  color: #0f766e;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  transition: all 0.2s ease;
}

.shopw-search-suggest-chip:hover {
  color: #0d9488;
  border-color: #2dd4bf;
  background: #f0fdfa;
  transform: translateY(-1px);
}

.shopw-search-suggest-links {
  display: grid;
  gap: 8px;
}

.shopw-search-suggest-shortcut {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  padding: 0 12px;
  border-radius: 14px;
  background: #fff;
  border: 1px solid #ccfbf1;
  color: #0f172a;
  text-decoration: none;
  font-size: 13px;
  font-weight: 700;
  transition: all 0.2s ease;
}

.shopw-search-suggest-shortcut:hover {
  color: #0d9488;
  border-color: #2dd4bf;
  background: #f0fdfa;
}

.shopw-search-suggest-results-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.shopw-search-suggest-results-head small {
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
}

.shopw-search-suggest-list {
  position: static !important;
  width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  box-shadow: none;
  display: grid;
  gap: 10px;
  background: transparent;
}

.shopw-search-suggest-list .li_search_ajax {
  list-style: none;
}

.shopw-search-suggest-list .li_search_ajax a {
  display: block;
  padding: 0;
  color: inherit;
}

.shopw-search-suggest-list .li_search_ajax a:hover {
  background: transparent;
  color: inherit;
}

.shopw-search-suggest-card {
  display: grid;
  grid-template-columns: 86px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  min-width: 0;
