.shopw-hero-main .hero-slot .shopw-hero-slide {
  transform: scale(1.02);
  transform-origin: center center;
  overflow: hidden;
}

.shopw-hero-main .hero-slot .shopw-hero-slide::before {
  content: "";
  position: absolute;
  inset: -12%;
  background:
    radial-gradient(circle at 16% 24%, rgba(255, 255, 255, 0.2), transparent 28%),
    linear-gradient(118deg, transparent 18%, rgba(255, 255, 255, 0.16) 46%, transparent 68%);
  opacity: 0;
  pointer-events: none;
}

.shopw-hero-slide-copy>* {
  opacity: 0;
  transform: translateY(18px);
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide {
  animation: shopwHeroKenBurns var(--shopw-hero-cycle) linear forwards;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide::before {
  animation: shopwHeroSweep var(--shopw-hero-cycle) ease-in-out forwards;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>* {
  animation: shopwHeroReveal 0.68s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>*:nth-child(1) {
  animation-delay: 0.08s;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>*:nth-child(2) {
  animation-delay: 0.16s;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>*:nth-child(3) {
  animation-delay: 0.24s;
}

.shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>*:nth-child(4) {
  animation-delay: 0.32s;
}

#slider .carousel-indicators li {
  position: relative;
  overflow: hidden;
}

#slider .carousel-indicators li::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.96));
  transform: scaleX(0);
  transform-origin: left center;
  opacity: 0;
}

#slider .carousel-indicators .active::after {
  opacity: 1;
  animation: shopwHeroIndicator var(--shopw-hero-cycle) linear forwards;
}

