@keyframes shopwHeroKenBurns {
  0% {
    transform: scale(1.02);
  }

  100% {
    transform: scale(1.08);
  }
}

@keyframes shopwHeroSweep {
  0% {
    opacity: 0;
    transform: translateX(-12%) scale(1.08);
  }

  18% {
    opacity: 0.8;
  }

  100% {
    opacity: 0;
    transform: translateX(10%) scale(1.16);
  }
}

@keyframes shopwHeroReveal {
  0% {
    opacity: 0;
    transform: translateY(18px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes shopwHeroIndicator {
  0% {
    transform: scaleX(0);
  }

  100% {
    transform: scaleX(1);
  }
}

@media (max-width: 991px) {
  .shopw-search-suggest-layout {
    grid-template-columns: 1fr;
  }

  .shopw-search-suggest-side {
    border-right: 0;
    border-bottom: 1px solid #f3d4d9;
  }

  .shopw-flash-sale-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .shopw-flash-sale-countdown {
    justify-content: flex-start;
  }
}

@media (max-width: 767px) {
  .shopw-search {
    min-height: 48px;
    height: 48px;
  }

  .shopw-search-btn {
    height: 48px;
  }

  .shopw-search-suggest {
    top: calc(100% + 8px);
  }

  .shopw-search-suggest-main,
  .shopw-search-suggest-side {
    padding: 14px;
  }

  .shopw-search-suggest-card {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .shopw-flash-sale-shell {
    padding: 18px;
    border-radius: 24px;
  }

  .shopw-flash-sale-copy .title {
    font-size: 28px;
  }

  .shopw-flash-sale-pill {
    min-width: 62px;
    min-height: 62px;
    border-radius: 16px;
  }

  .shopw-flash-sale-pill strong {
    font-size: 20px;
  }

  .shopw-flash-sale-track {
    display: flex;
    gap: 14px;
    overflow-x: auto;
    padding-bottom: 6px;
    scroll-snap-type: x mandatory;
  }

  .shopw-flash-sale-card {
    flex: 0 0 min(82vw, 282px);
    scroll-snap-align: start;
  }

  .shopw-flash-sale-pricing strong {
    font-size: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shopw-hero-main .hero-slot .item.active .shopw-hero-slide,
  .shopw-hero-main .hero-slot .item.active .shopw-hero-slide::before,
  .shopw-hero-main .hero-slot .item.active .shopw-hero-slide-copy>*,
  #slider .carousel-indicators .active::after {
    animation: none !important;
  }

  .shopw-flash-sale-link,
  .shopw-search-suggest-card {
    transition: none;
  }
}

