  .shopw-footer-main {
    gap: 14px;
  }

  .shopw-footer-brand-card,
  .shopw-footer-card {
    padding: 18px;
    border-radius: 22px;
  }

  .shopw-footer-kicker {
    min-height: 28px;
    margin-bottom: 10px;
    padding: 0 10px;
    font-size: 10px;
  }

  .shopw-footer-brand-card h2,
  .shopw-footer-card h3 {
    font-size: 24px;
    line-height: 1.14;
  }

  .shopw-footer-contact-grid,
