  }

  .shopw-footer-newsletter-form button {
    width: 100%;
  }

  .shopw-footer-bottom-inner {
    width: calc(100% - 20px);
    min-height: 58px;
    font-size: 12px;
  }
}


/* Product Card Hover & Specs */
.shopw-product-card {
    position: relative;
    overflow: visible;
    z-index: 1;
    transition: all 0.3s ease;
}

.shopw-product-card:hover {
    z-index: 100;
}

.shopw-product-specs-preview {
    display: block;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px dashed #eee;
    text-align: left;
    min-height: 45px;
}

.shopw-product-spec-item {
    font-size: 11px;
    color: #475569;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-right: 6px;
    background: #f1f5f9;
    padding: 3px 8px;
    border-radius: 6px;
    margin-bottom: 6px;
    font-weight: 600;
}

.shopw-product-hover-info {
    position: absolute;
    top: 0;
    left: calc(100% + 10px);
    width: 280px;
    background: #fff;
    box-shadow: 0 15px 45px rgba(15, 23, 42, 0.18);
    border-radius: 16px;
    padding: 24px;
    opacity: 0;
    visibility: hidden;
    transform: translateX(20px);
    transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    pointer-events: none;
    z-index: 200;
    border: 1px solid rgba(226, 232, 240, 0.8);
    text-align: left;
}

.shopw-product-card:hover .shopw-product-hover-info {
    opacity: 1;
    visibility: visible;
    transform: translateX(0);
}

.col-sm-3:nth-child(4n) .shopw-product-hover-info {
    left: auto;
    right: calc(100% + 10px);
    transform: translateX(-20px);
}

.shopw-hover-info-title {
    font-size: 15px;
    font-weight: 800;
    color: #0f172a;
    margin-bottom: 16px;
    position: relative;
    padding-bottom: 8px;
}

.shopw-hover-info-title::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 40px;
    height: 3px;
    background: #00bcd4;
    border-radius: 2px;
}

.shopw-hover-info-list {
 list-style: none;
 padding: 0;
 margin: 0;
 display: grid;
 gap: 10px;
}

.shopw-hover-info-item {
 font-size: 13px;
 color: #475569;
 display: flex;
 align-items: flex-start;
 gap: 12px;
 line-height: 1.4;
}

.shopw-hover-info-item i {
 width: 18px;
 color: #00bcd4;
 font-size: 14px;
 margin-top: 2px;
 flex-shrink: 0;
}


/* PDP Specs Table */
.shopw-pdp-specs-section {
    margin: 60px 0;
