    border-color: rgba(0, 101, 255, 0.28) !important;
    color: #0065FF !important;
}

.g-category .shopw-category-results .row,
.g-search .shopw-search-grid,
.g-product-detail .shopw-related-grid {
    display: flex;
    flex-wrap: wrap;
}

.g-category .shopw-category-results .row > [class*="col-"],
.g-search .shopw-search-grid > [class*="col-"],
.g-product-detail .shopw-related-grid > [class*="col-"] {
    display: flex;
    margin-bottom: 20px;
}

.g-category .shopw-product-card,
.g-search .shopw-product-card,
.g-product-detail .shopw-pdp-related .shopw-product-card {
    width: 100%;
}

.shopw-compare-notice {
    margin: 0;
    border: 1px solid #bae6fd;
    border-radius: 16px;
    background: #f0f9ff;
    color: #075985;
    font-weight: 700;
}

@media (max-width: 991px) {
    .shopw-product-hover-info {
        display: none;
    }
}

@media (max-width: 767px) {
    .g-category .shopw-category-toolbar-card,
    .g-category .shopw-category-results,
    .g-search .shopw-search-results,
    .g-compare .shopw-compare-summary,
    .g-compare .shopw-compare-table-shell {
        padding: 16px;
        border-radius: 16px;
    }

    .g-category .shopw-product-media,
    .g-search .shopw-product-media,
    .g-product-detail .shopw-pdp-related .shopw-product-media {
        min-height: 180px;
    }

    .shopw-card-actions {
        gap: 8px;
    }

    .shopw-card-meta-list {
