    }

    .g-compare .shopw-compare-table {
        min-width: 640px;
    }
}



/* ========================================
   CATALOG PAGE (/san-pham)
   ======================================== */

.dd-catalog-page {
    padding: 2rem 0;
    max-width: 1400px;
    margin: 0 auto;
}

.dd-catalog-breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 1rem 1.5rem;
    font-size: 0.875rem;
    color: #64748b;
}

.dd-catalog-breadcrumb a {
    color: #3b82f6;
    text-decoration: none;
    transition: color 0.2s;
}

.dd-catalog-breadcrumb a:hover {
    color: #2563eb;
    text-decoration: underline;
}

.dd-catalog-breadcrumb strong {
    color: #1e293b;
}

.dd-catalog-hero {
    background: linear-gradient(135deg, #4A9B9B 0%, #5DADE2 100%);
    color: white;
    padding: 3rem 1.5rem;
    border-radius: 1rem;
    margin: 0 1.5rem 2rem;
    position: relative;
    overflow: hidden;
}

.dd-catalog-hero-content {
    position: relative;
    z-index: 2;
}

.dd-catalog-breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 1rem;
}

.dd-catalog-breadcrumb a {
    color: rgba(255, 255, 255, 0.95);
    text-decoration: none;
    transition: color 0.2s;
}

.dd-catalog-breadcrumb a:hover {
    color: white;
    text-decoration: underline;
}

.dd-catalog-breadcrumb span {
    color: rgba(255, 255, 255, 0.7);
}

.dd-catalog-breadcrumb strong {
    color: white;
    font-weight: 600;
}

.dd-catalog-hero-desc {
    font-size: 1rem;
    opacity: 0.95;
    line-height: 1.6;
    margin: 0.75rem 0 1.5rem;
}

.dd-catalog-hero h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin: 0 0 1rem;
    line-height: 1.2;
}

.dd-catalog-hero p {
    font-size: 1.125rem;
    opacity: 0.95;
    line-height: 1.6;
    margin: 0;
}

.dd-catalog-hero-meta {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 1rem;
    max-width: 600px;
}

.dd-catalog-meta-card {
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(10px);
    padding: 1rem 1.25rem;
    border-radius: 0.75rem;
    border: 1px solid rgba(255, 255, 255, 0.3);
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.dd-catalog-meta-card span {
    font-size: 0.75rem;
    opacity: 0.9;
    font-weight: 500;
}

.dd-catalog-meta-card strong {
    font-size: 1.25rem;
    font-weight: 700;
    display: block;
}

.dd-catalog-hero-actions {
    position: absolute;
    bottom: 1.5rem;
    right: 1.5rem;
    display: flex;
    gap: 0.75rem;
    z-index: 3;
}

.dd-hero-action-btn {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.4);
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
}

.dd-hero-action-btn:hover {
    background: rgba(255, 255, 255, 0.35);
    transform: scale(1.05);
}

.dd-catalog-container {
    display: grid;
    grid-template-columns: 280px 1fr;
    gap: 2rem;
    padding: 0 1.5rem;
}

@media (max-width: 991px) {
    .dd-catalog-container {
        grid-template-columns: 1fr;
    }
}

/* Sidebar Filters */
.dd-catalog-sidebar {
    position: sticky;
    top: 2rem;
    height: fit-content;
}

.dd-catalog-filter-form {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1.5rem;
}

.dd-filter-section {
    padding: 1.5rem 0;
    border-bottom: 1px solid #e2e8f0;
}

.dd-filter-section:first-child {
    padding-top: 0;
}

.dd-filter-section:last-of-type {
    border-bottom: none;
}

.dd-filter-section h2 {
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 1rem;
    color: #1e293b;
}

.dd-filter-section label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.5rem 0;
    cursor: pointer;
    transition: color 0.2s;
}

.dd-filter-section label:hover {
    color: #4A9B9B;
}

.dd-filter-section input[type="radio"],
.dd-filter-section input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.dd-filter-section span {
    font-size: 0.9375rem;
}

.dd-filter-input {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.dd-filter-input span {
    font-size: 0.875rem;
    font-weight: 500;
    color: #475569;
}

.dd-filter-input input {
    padding: 0.625rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    font-size: 0.9375rem;
    transition: border-color 0.2s;
}

.dd-filter-input input:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-filter-primary {
    width: 100%;
    padding: 0.75rem;
    background: #4A9B9B;
    color: white;
    border: none;
    border-radius: 0.5rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.dd-filter-primary:hover {
    background: #3d8585;
}

.dd-filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    padding-top: 1.5rem;
}

.dd-filter-actions a {
    text-align: center;
    padding: 0.75rem;
    color: #64748b;
    text-decoration: none;
    border: 1px solid #e2e8f0;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.dd-filter-actions a:hover {
    color: #4A9B9B;
    border-color: #4A9B9B;
}

/* Main Content */
.dd-catalog-main {
    min-width: 0;
}

.dd-catalog-toolbar {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1.5rem;
    margin-bottom: 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 2rem;
    flex-wrap: wrap;
}

.dd-catalog-toolbar-left {
    flex: 1;
}

.dd-catalog-result-title {
    font-size: 1.125rem;
    font-weight: 600;
    margin: 0;
    color: #1e293b;
}

.dd-active-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.dd-active-filters span {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background: #f1f5f9;
    color: #475569;
    font-size: 0.875rem;
    border-radius: 0.375rem;
}

.dd-sort-form {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.dd-sort-form label {
    font-size: 0.9375rem;
    font-weight: 500;
    color: #475569;
}

.dd-sort-form select {
    padding: 0.625rem 2.5rem 0.625rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    font-size: 0.9375rem;
    background: white;
    cursor: pointer;
    transition: border-color 0.2s;
}

.dd-sort-form select:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-catalog-searchbar {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1rem 1.5rem;
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 1rem;
}

.dd-catalog-searchbar input[type="search"] {
    flex: 1;
    padding: 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    font-size: 1rem;
}

.dd-catalog-searchbar input[type="search"]:focus {
    outline: none;
    border-color: #3b82f6;
}

.dd-catalog-searchbar button {
    padding: 0.75rem 1.5rem;
    background: #3b82f6;
    color: white;
    border: none;
    border-radius: 0.5rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.dd-catalog-searchbar button:hover {
    background: #2563eb;
}

.dd-view-toggle {
    display: flex;
    gap: 0.5rem;
    padding: 0.5rem;
    background: #f1f5f9;
    border-radius: 0.5rem;
}

.dd-view-toggle i {
    padding: 0.5rem;
    cursor: pointer;
    transition: color 0.2s;
}

.dd-view-toggle i:hover {
    color: #3b82f6;
}

/* Product Grid */
.dd-product-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
    margin-bottom: 2rem;
}

@media (max-width: 1200px) {
    .dd-product-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 768px) {
    .dd-product-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 1rem;
    }
}

@media (max-width: 480px) {
    .dd-product-grid {
        grid-template-columns: 1fr;
    }
}

.dd-product-card {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    overflow: hidden;
    transition: all 0.3s;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.dd-product-card:hover {
    box-shadow: 0 8px 24px rgba(74, 155, 155, 0.15);
    transform: translateY(-2px);
    border-color: #4A9B9B;
}

.dd-product-media {
    display: block;
    aspect-ratio: 1;
    overflow: hidden;
    background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
    padding: 1rem;
}

.dd-product-media img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    transition: transform 0.3s;
}

.dd-product-card:hover .dd-product-media img {
    transform: scale(1.05);
}

.dd-product-info {
    padding: 1rem 1.25rem;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.dd-product-code {
    display: block;
    font-size: 0.75rem;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: 600;
}

.dd-product-name {
    font-size: 0.9375rem;
    font-weight: 600;
    margin: 0;
    line-height: 1.4;
    flex: 1;
}

.dd-product-name a {
    color: #1e293b;
    text-decoration: none;
    transition: color 0.2s;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.dd-product-name a:hover {
    color: #4A9B9B;
}

.dd-product-price-section {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    flex-wrap: wrap;
    margin-top: auto;
}

.dd-product-price-original {
    font-size: 0.875rem;
    color: #94a3b8;
    text-decoration: line-through;
    font-weight: 500;
}

.dd-product-price-current {
    font-size: 1.125rem;
    font-weight: 700;
    color: #dc2626;
}

.dd-product-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    padding: 0 1.25rem 1.25rem;
    border-top: 1px solid #f1f5f9;
    padding-top: 1rem;
}

.dd-btn-detail,
.dd-btn-cart {
    padding: 0.625rem 1rem;
    text-align: center;
    font-weight: 600;
    border-radius: 0.5rem;
    transition: all 0.2s;
    cursor: pointer;
    font-size: 0.875rem;
    border: none;
}

.dd-btn-detail {
    background: white;
    color: #4A9B9B;
    text-decoration: none;
    border: 1px solid #4A9B9B;
}

.dd-btn-detail:hover {
    background: #f0f9f9;
    color: #3d8585;
    border-color: #3d8585;
}

.dd-btn-cart {
    background: #4A9B9B;
    color: white;
}

.dd-btn-cart:hover {
    background: #3d8585;
}

/* Pagination */
.dd-catalog-pagination {
    display: flex;
    justify-content: center;
    padding: 2rem 0;
}

.dd-catalog-pagination .pagination {
    display: flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.dd-catalog-pagination .pagination li {
    display: block;
}

.dd-catalog-pagination .pagination a,
.dd-catalog-pagination .pagination span {
    display: block;
    padding: 0.625rem 1rem;
    border: 1px solid #e2e8f0;
    border-radius: 0.5rem;
    color: #475569;
    text-decoration: none;
    transition: all 0.2s;
}

.dd-catalog-pagination .pagination a:hover {
    background: #f0f9f9;
    border-color: #4A9B9B;
    color: #4A9B9B;
}

.dd-catalog-pagination .pagination .active span {
    background: #4A9B9B;
    color: white;
    border-color: #4A9B9B;
}

.dd-catalog-pagination .pagination .disabled span {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Responsive Adjustments */
@media (max-width: 991px) {
    .dd-catalog-hero {
        margin: 0 1rem 1.5rem;
        padding: 2rem 1.25rem;
    }

    .dd-catalog-hero h1 {
        font-size: 2rem;
    }

    .dd-catalog-hero-meta {
        grid-template-columns: 1fr;
    }

    .dd-catalog-container {
        padding: 0 1rem;
    }

    .dd-catalog-sidebar {
        position: static;
    }
}

@media (max-width: 768px) {
    .dd-catalog-hero h1 {
        font-size: 1.75rem;
    }

    .dd-catalog-hero-actions {
        bottom: 1rem;
        right: 1rem;
    }

    .dd-hero-action-btn {
        width: 40px;
        height: 40px;
    }

    .dd-catalog-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .dd-sort-form {
        width: 100%;
        justify-content: space-between;
    }

    .dd-sort-form select {
        flex: 1;
    }
}

@media (max-width: 480px) {
    .dd-catalog-hero {
        padding: 1.5rem 1rem;
        margin: 0 0.5rem 1rem;
    }

    .dd-catalog-hero h1 {
        font-size: 1.5rem;
    }

    .dd-catalog-container {
        padding: 0 0.5rem;
    }

    .dd-product-actions {
        grid-template-columns: 1fr;
    }

    .dd-catalog-pagination .pagination {
        grid-template-columns: 1fr;
    }
}


/* ========================================
   Product Detail Page (PDP) - Teal Design
   ======================================== */

.dd-pdp-page {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

.dd-pdp-breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 2rem;
    font-size: 0.875rem;
    color: #64748b;
}

.dd-pdp-breadcrumb a {
    color: #4A9B9B;
    text-decoration: none;
    transition: color 0.2s;
}

.dd-pdp-breadcrumb a:hover {
    color: #3d8585;
    text-decoration: underline;
}

.dd-pdp-breadcrumb span {
    color: #cbd5e1;
}

.dd-pdp-breadcrumb strong {
    color: #1e293b;
    font-weight: 600;
}

.dd-pdp-main {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    margin-bottom: 3rem;
}

/* Gallery */
.dd-pdp-gallery {
    position: sticky;
    top: 2rem;
    height: fit-content;
}

.dd-pdp-gallery-list {
    list-style: none;
    padding: 0;
    margin: 0;
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    overflow: hidden;
}

.dd-pdp-gallery-list li {
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
}

.dd-pdp-gallery-list img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.dd-pdp-gallery-hint {
    text-align: center;
    color: #64748b;
    font-size: 0.875rem;
    margin-top: 1rem;
}

/* Product Info */
.dd-pdp-info {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.dd-pdp-header {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.dd-pdp-category-label {
    color: #4A9B9B;
    font-size: 0.875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.dd-pdp-title {
    font-size: 2rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
    line-height: 1.3;
}

.dd-pdp-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.dd-pdp-stars {
    display: flex;
    gap: 0.25rem;
    color: #fbbf24;
}

.dd-pdp-stars .fa-star-o {
    color: #cbd5e1;
}

.dd-pdp-rating-text {
    color: #64748b;
    font-size: 0.875rem;
}

.dd-pdp-description {
    color: #475569;
    font-size: 0.9375rem;
    line-height: 1.6;
    margin: 0;
}

.dd-pdp-badges {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.dd-pdp-sku {
    display: inline-flex;
    align-items: center;
    padding: 0.375rem 0.875rem;
    background: #EF4444;
    color: white;
    font-size: 0.875rem;
    font-weight: 700;
    border-radius: 0.375rem;
}

.dd-pdp-stock {
    display: inline-flex;
    align-items: center;
    padding: 0.375rem 0.875rem;
    background: #10b981;
    color: white;
    font-size: 0.875rem;
    font-weight: 600;
    border-radius: 0.375rem;
}

.dd-pdp-stock.is-out-stock {
    background: #94a3b8;
}

/* Purchase Section */
.dd-pdp-purchase-section {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
}

.dd-pdp-quantity label {
    display: block;
    font-size: 0.875rem;
    font-weight: 600;
    color: #475569;
    margin-bottom: 0.5rem;
}

.dd-pdp-qty-control {
    display: flex;
    align-items: center;
    gap: 0;
    width: fit-content;
}

.dd-qty-btn {
    width: 40px;
    height: 40px;
    border: 1px solid #cbd5e1;
    background: white;
    color: #475569;
    font-size: 1.25rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.dd-qty-minus {
    border-radius: 0.5rem 0 0 0.5rem;
}

.dd-qty-plus {
    border-radius: 0 0.5rem 0.5rem 0;
}

.dd-qty-btn:hover {
    background: #4A9B9B;
    color: white;
    border-color: #4A9B9B;
}

.dd-qty-input {
    width: 60px;
    height: 40px;
    border: 1px solid #cbd5e1;
    border-left: 0;
    border-right: 0;
    text-align: center;
    font-size: 1rem;
    font-weight: 600;
    color: #0f172a;
}

.dd-qty-input:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-pdp-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
}

.dd-btn-add-cart,
.dd-btn-buy-now {
    padding: 0.875rem 1.5rem;
    font-size: 0.9375rem;
    font-weight: 600;
    border-radius: 0.5rem;
    cursor: pointer;
    transition: all 0.2s;
    border: none;
}

.dd-btn-add-cart {
    background: white;
    color: #4A9B9B;
    border: 2px solid #4A9B9B;
}

.dd-btn-add-cart:hover {
    background: #f0f9f9;
    color: #3d8585;
    border-color: #3d8585;
}

.dd-btn-buy-now {
    background: #4A9B9B;
    color: white;
}

.dd-btn-buy-now:hover {
    background: #3d8585;
}

.dd-btn-add-cart:disabled,
.dd-btn-buy-now:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.dd-pdp-quick-actions {
    display: flex;
    gap: 1rem;
    padding-top: 0.75rem;
    border-top: 1px solid #e2e8f0;
}

.dd-quick-action {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0;
    background: none;
    border: none;
    color: #64748b;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.2s;
}

.dd-quick-action:hover {
    color: #4A9B9B;
}

.dd-pdp-purchase-status {
    min-height: 1.5rem;
    color: #10b981;
    font-size: 0.875rem;
    font-weight: 600;
}

/* Features */
.dd-pdp-features {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
}

.dd-pdp-feature-card {
    display: flex;
    gap: 1rem;
    padding: 1rem;
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 0.75rem;
}

.dd-pdp-feature-card i {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e0f2f2;
    color: #4A9B9B;
    border-radius: 0.5rem;
    font-size: 1.25rem;
    flex-shrink: 0;
}

.dd-pdp-feature-card strong {
    display: block;
    color: #0f172a;
    font-size: 0.9375rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.dd-pdp-feature-card p {
    color: #64748b;
    font-size: 0.875rem;
    line-height: 1.5;
    margin: 0;
}

/* Specs Table */
.dd-pdp-specs-table {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 0.75rem;
    overflow: hidden;
}

.dd-pdp-spec-row {
    display: grid;
    grid-template-columns: 140px 1fr;
    gap: 1rem;
    padding: 0.875rem 1.25rem;
    border-bottom: 1px solid #f1f5f9;
}

.dd-pdp-spec-row:last-child {
    border-bottom: none;
}

.dd-pdp-spec-row span {
    color: #64748b;
    font-size: 0.875rem;
    font-weight: 500;
}

.dd-pdp-spec-row strong,
.dd-pdp-spec-row a {
    color: #0f172a;
    font-size: 0.9375rem;
    font-weight: 600;
}

.dd-pdp-spec-row a {
    color: #4A9B9B;
    text-decoration: none;
}

.dd-pdp-spec-row a:hover {
    text-decoration: underline;
}

/* Attributes */
.dd-pdp-attributes {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 0.75rem;
    padding: 1.5rem;
}

.dd-pdp-attributes h3 {
    font-size: 1rem;
    font-weight: 600;
    color: #0f172a;
    margin: 0 0 1rem;
}

.dd-pdp-attribute-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: 1rem;
}

.dd-pdp-attribute-item {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    padding: 1rem;
    border: 2px solid #e2e8f0;
    border-radius: 0.75rem;
    cursor: pointer;
    transition: all 0.2s;
}

.dd-pdp-attribute-item:hover {
    border-color: #4A9B9B;
    background: #f0f9f9;
}

.dd-pdp-attribute-item img {
    width: 100%;
    aspect-ratio: 1;
    object-fit: contain;
    border-radius: 0.5rem;
    background: #f8fafc;
}

.dd-pdp-attribute-item strong {
    display: block;
    font-size: 0.875rem;
    font-weight: 600;
    color: #0f172a;
}

.dd-pdp-attribute-item span {
    display: block;
    font-size: 0.875rem;
    color: #4A9B9B;
    font-weight: 600;
}

/* Tabs */
.dd-pdp-tabs {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    overflow: hidden;
    margin-bottom: 3rem;
}

.dd-pdp-tabs-nav {
    display: flex;
    border-bottom: 1px solid #e2e8f0;
    background: #f8fafc;
}

.dd-tab-btn {
    flex: 1;
    padding: 1rem 1.5rem;
    background: none;
    border: none;
    color: #64748b;
    font-size: 0.9375rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    border-bottom: 3px solid transparent;
}

.dd-tab-btn:hover {
    color: #4A9B9B;
    background: white;
}

.dd-tab-btn.active {
    color: #4A9B9B;
    background: white;
    border-bottom-color: #4A9B9B;
}

.dd-pdp-tabs-content {
    padding: 2rem;
}

.dd-tab-pane {
    display: none;
}

.dd-tab-pane.active {
    display: block;
}

.dd-tab-pane h3 {
    font-size: 1.5rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 1.5rem;
}

.dd-tab-pane h4 {
    font-size: 1.125rem;
    font-weight: 600;
    color: #0f172a;
    margin: 2rem 0 1rem;
}

/* Reviews */
.dd-pdp-review-summary {
    padding: 1.5rem;
    background: #f8fafc;
    border-radius: 0.75rem;
    margin-bottom: 2rem;
}

.dd-pdp-review-summary strong {
    font-size: 1.125rem;
    color: #0f172a;
}

.dd-pdp-review-list {
    margin-bottom: 2rem;
}

.dd-pdp-review-form {
    padding: 1.5rem;
    background: #f8fafc;
    border-radius: 0.75rem;
}

.dd-pdp-review-fields {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin: 1.5rem 0;
}

.dd-pdp-review-fields input,
.dd-pdp-review-fields textarea {
    padding: 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    font-size: 0.9375rem;
}

.dd-pdp-review-fields input:focus,
.dd-pdp-review-fields textarea:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-pdp-review-fields textarea {
    min-height: 120px;
    resize: vertical;
}

.dd-btn-submit-review {
    padding: 0.75rem 1.5rem;
    background: #4A9B9B;
    color: white;
    border: none;
    border-radius: 0.5rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.dd-btn-submit-review:hover {
    background: #3d8585;
}

/* Related & Recommended */
.dd-pdp-related,
.dd-pdp-recommended {
    margin-bottom: 3rem;
}

.dd-section-title {
    font-size: 1.75rem;
    font-weight: 700;
    color: #0f172a;
    text-align: center;
    margin: 0 0 2rem;
}

.dd-product-grid--4col {
    grid-template-columns: repeat(4, 1fr);
}

/* Responsive */
@media (max-width: 1200px) {
    .dd-pdp-main {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .dd-pdp-gallery {
        position: static;
    }

    .dd-product-grid--4col {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 768px) {
    .dd-pdp-page {
        padding: 1rem;
    }

    .dd-pdp-title {
        font-size: 1.5rem;
    }

    .dd-pdp-features {
        grid-template-columns: 1fr;
    }

    .dd-pdp-actions {
        grid-template-columns: 1fr;
    }

    .dd-pdp-tabs-nav {
        flex-direction: column;
    }

    .dd-tab-btn {
        border-bottom: 1px solid #e2e8f0;
        border-left: 3px solid transparent;
    }

    .dd-tab-btn.active {
        border-bottom-color: #e2e8f0;
        border-left-color: #4A9B9B;
    }

    .dd-pdp-tabs-content {
        padding: 1.5rem;
    }

    .dd-product-grid--4col {
        grid-template-columns: repeat(2, 1fr);
    }

    .dd-pdp-spec-row {
        grid-template-columns: 1fr;
        gap: 0.5rem;
    }
}

@media (max-width: 480px) {
    .dd-pdp-breadcrumb {
        font-size: 0.75rem;
    }

    .dd-pdp-title {
        font-size: 1.25rem;
    }

    .dd-pdp-quick-actions {
        flex-direction: column;
        gap: 0.5rem;
    }

    .dd-product-grid--4col {
        grid-template-columns: 1fr;
    }

    .dd-section-title {
        font-size: 1.5rem;
    }
}


/* ========================================
   Cart Page - Teal Design
   ======================================== */

.dd-cart-page {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

.dd-cart-breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 2rem;
    font-size: 0.875rem;
    color: #64748b;
}

.dd-cart-breadcrumb a {
    color: #4A9B9B;
    text-decoration: none;
    transition: color 0.2s;
}

.dd-cart-breadcrumb a:hover {
    color: #3d8585;
    text-decoration: underline;
}

.dd-cart-breadcrumb span {
    color: #cbd5e1;
}

.dd-cart-breadcrumb strong {
    color: #1e293b;
    font-weight: 600;
}

/* Alerts */
.dd-cart-alert {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.5rem;
    border-radius: 0.75rem;
    margin-bottom: 1.5rem;
    font-size: 0.9375rem;
}

.dd-cart-alert--success {
    background: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}

.dd-cart-alert--error {
    background: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.dd-cart-alert i {
    font-size: 1.25rem;
}

/* Container */
.dd-cart-container {
    display: grid;
    grid-template-columns: 1fr 380px;
    gap: 2rem;
    align-items: start;
}

/* Main */
.dd-cart-main {
    min-width: 0;
}

.dd-cart-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 1.5rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* Empty State */
.dd-cart-empty {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 3rem 2rem;
    text-align: center;
}

.dd-cart-empty-icon {
    width: 80px;
    height: 80px;
    margin: 0 auto 1.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f1f5f9;
    border-radius: 50%;
    color: #94a3b8;
    font-size: 2.5rem;
}

.dd-cart-empty-message {
    font-size: 1.25rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 0.5rem;
}

.dd-cart-empty-hint {
    color: #64748b;
    font-size: 0.9375rem;
    line-height: 1.6;
    margin: 0 0 2rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.dd-cart-empty-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

/* Cart Items */
.dd-cart-form {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1.5rem;
    margin-bottom: 2rem;
}

.dd-cart-items {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.dd-cart-item {
    display: grid;
    grid-template-columns: 100px 1fr auto auto auto auto;
    gap: 1.5rem;
    align-items: center;
    padding: 1rem;
    border: 1px solid #f1f5f9;
    border-radius: 0.75rem;
    background: #fafafa;
    position: relative;
}

.dd-cart-item-media {
    width: 100px;
    height: 100px;
    border-radius: 0.5rem;
    overflow: hidden;
    background: white;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dd-cart-item-media img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.dd-cart-item-info {
    flex: 1;
    min-width: 0;
}

.dd-cart-item-name {
    font-size: 1rem;
    font-weight: 600;
    color: #0f172a;
    margin: 0 0 0.25rem;
    line-height: 1.4;
}

.dd-cart-item-sku {
    font-size: 0.875rem;
    color: #64748b;
    margin: 0;
}

.dd-cart-item-variant {
    font-size: 0.875rem;
    color: #64748b;
    margin: 0.25rem 0 0;
}

.dd-cart-item-price {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.25rem;
    min-width: 120px;
}

.dd-cart-item-price-original {
    font-size: 0.875rem;
    color: #94a3b8;
    text-decoration: line-through;
}

.dd-cart-item-price-current {
    font-size: 1.125rem;
    font-weight: 700;
    color: #0f172a;
}

.dd-cart-item-quantity {
    display: flex;
    align-items: center;
    gap: 0;
}

.dd-qty-btn {
    width: 36px;
    height: 36px;
    border: 1px solid #cbd5e1;
    background: white;
    color: #475569;
    font-size: 1.125rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.dd-qty-btn:first-child {
    border-radius: 0.375rem 0 0 0.375rem;
}

.dd-qty-btn:last-child {
    border-radius: 0 0.375rem 0.375rem 0;
}

.dd-qty-btn:hover {
    background: #4A9B9B;
    color: white;
    border-color: #4A9B9B;
}

.dd-qty-input {
    width: 50px;
    height: 36px;
    border: 1px solid #cbd5e1;
    border-left: 0;
    border-right: 0;
    text-align: center;
    font-size: 0.9375rem;
    font-weight: 600;
    color: #0f172a;
}

.dd-qty-input:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-cart-item-total {
    min-width: 120px;
    text-align: right;
}

.dd-cart-item-total strong {
    font-size: 1.125rem;
    font-weight: 700;
    color: #0f172a;
}

.dd-cart-item-remove {
    width: 32px;
    height: 32px;
    border: none;
    background: #fee2e2;
    color: #dc2626;
    border-radius: 0.375rem;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dd-cart-item-remove:hover {
    background: #dc2626;
    color: white;
}

/* Cart Actions */
.dd-cart-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

/* Buttons */
.dd-btn-primary,
.dd-btn-secondary,
.dd-btn-checkout {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.75rem 1.5rem;
    font-size: 0.9375rem;
    font-weight: 600;
    border-radius: 0.5rem;
    cursor: pointer;
    transition: all 0.2s;
    text-decoration: none;
    border: none;
}

.dd-btn-primary {
    background: #4A9B9B;
    color: white;
}

.dd-btn-primary:hover {
    background: #3d8585;
    color: white;
}

.dd-btn-secondary {
    background: white;
    color: #4A9B9B;
    border: 1px solid #4A9B9B;
}

.dd-btn-secondary:hover {
    background: #f0f9f9;
    color: #3d8585;
    border-color: #3d8585;
}

.dd-btn-checkout {
    width: 100%;
    background: #4A9B9B;
    color: white;
    font-size: 1rem;
}

.dd-btn-checkout:hover {
    background: #3d8585;
    color: white;
}

.dd-btn-checkout:disabled {
    background: #cbd5e1;
    color: #94a3b8;
    cursor: not-allowed;
}

.dd-btn-link {
    color: #64748b;
    text-decoration: none;
    font-size: 0.9375rem;
    font-weight: 500;
    transition: color 0.2s;
}

.dd-btn-link:hover {
    color: #4A9B9B;
}

/* Sidebar */
.dd-cart-sidebar {
    position: sticky;
    top: 2rem;
}

.dd-cart-summary {
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    padding: 1.5rem;
}

.dd-cart-summary h2 {
    font-size: 1rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 1.5rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.dd-cart-summary-rows {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e2e8f0;
}

.dd-cart-summary-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.dd-cart-summary-row span {
    color: #64748b;
    font-size: 0.9375rem;
}

.dd-cart-summary-row strong {
    color: #0f172a;
    font-size: 1rem;
    font-weight: 600;
}

.dd-cart-summary-row strong.is-discount {
    color: #dc2626;
}

.dd-link-continue {
    display: block;
    text-align: center;
    color: #64748b;
    text-decoration: none;
    font-size: 0.9375rem;
    margin-top: 1rem;
    transition: color 0.2s;
}

.dd-link-continue:hover {
    color: #4A9B9B;
}

/* Coupon */
.dd-cart-coupon {
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e2e8f0;
}

.dd-cart-coupon h3 {
    font-size: 0.9375rem;
    font-weight: 600;
    color: #0f172a;
    margin: 0 0 1rem;
}

.dd-cart-coupon-form {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.dd-coupon-input {
    padding: 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    font-size: 0.9375rem;
}

.dd-coupon-input:focus {
    outline: none;
    border-color: #4A9B9B;
}

.dd-btn-apply-coupon {
    padding: 0.75rem;
    background: white;
    color: #4A9B9B;
    border: 1px solid #4A9B9B;
    border-radius: 0.5rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.dd-btn-apply-coupon:hover {
    background: #f0f9f9;
    color: #3d8585;
    border-color: #3d8585;
}

.dd-cart-coupon-active {
    margin-top: 1rem;
    padding: 0.75rem;
    background: #d1fae5;
    border: 1px solid #6ee7b7;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    color: #065f46;
}

.dd-link-remove-coupon {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    color: #dc2626;
    text-decoration: none;
    font-size: 0.875rem;
    margin-top: 0.5rem;
}

.dd-link-remove-coupon:hover {
    text-decoration: underline;
}

/* Viewed Products */
.dd-cart-viewed {
    margin-top: 3rem;
}

.dd-cart-viewed h2 {
    font-size: 1.25rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 1.5rem;
}

.dd-cart-viewed-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
}

/* Responsive */
@media (max-width: 1200px) {
    .dd-cart-container {
        grid-template-columns: 1fr 320px;
    }

    .dd-cart-item {
        grid-template-columns: 80px 1fr auto auto;
        gap: 1rem;
    }

    .dd-cart-item-media {
        width: 80px;
        height: 80px;
    }

    .dd-cart-item-price,
    .dd-cart-item-total {
        min-width: 100px;
    }

    .dd-cart-item-quantity {
        grid-column: 1 / -1;
        justify-content: flex-start;
        margin-top: 0.5rem;
    }

    .dd-cart-item-remove {
        position: absolute;
        top: 0.5rem;
        right: 0.5rem;
    }

    .dd-cart-viewed-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 991px) {
    .dd-cart-container {
        grid-template-columns: 1fr;
    }

    .dd-cart-sidebar {
        position: static;
    }

    .dd-cart-viewed-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
