:root {
    --tech-cyan: #06b6d4;
    --tech-teal: #0f766e;
    --tech-blue: #0284c7;
    --tech-ink: #0f172a;
    --tech-muted: #64748b;
    --tech-line: #dbeafe;
    --tech-soft: #ecfeff;
    --tech-card: #ffffff;
    --tech-hot: #ef4444;
    --tech-amber: #f59e0b;
    --tech-radius: 24px;
    --tech-shadow: 0 24px 70px rgba(15, 23, 42, 0.12);
}

* {
    box-sizing: border-box;
}

body.tech-home {
    margin: 0;
    min-height: 100vh;
    font-family: "Be Vietnam Pro", sans-serif;
    color: var(--tech-ink);
    background:
        radial-gradient(circle at 12% 12%, rgba(6, 182, 212, 0.16), transparent 32%),
        radial-gradient(circle at 90% 8%, rgba(14, 165, 233, 0.16), transparent 26%),
        linear-gradient(180deg, #f8feff 0%, #eefcff 38%, #f8fafc 100%);
}

.tech-home a {
    color: inherit;
    text-decoration: none;
}

.tech-home a:hover,
.tech-home a:focus {
    text-decoration: none;
}

.tech-navbar {
    position: sticky;
    top: 0;
    z-index: 20;
    background: linear-gradient(90deg, var(--tech-cyan) 0%, #22d3ee 52%, var(--tech-teal) 100%);
    box-shadow: 0 14px 35px rgba(8, 145, 178, 0.24);
}

.tech-navbar .container {
    width: 100%;
    max-width: none;
    padding-right: 24px;
    padding-left: 24px;
}

.tech-navbar-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    min-height: 90px;
}

.tech-brand {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    flex: 0 0 auto;
    color: #fff;
}

.tech-brand-logo,
.tech-footer-logo {
    display: grid;
    place-items: center;
    width: 54px;
    height: 54px;
    overflow: hidden;
    border-radius: 999px;
    background: #fff;
    box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.8), 0 12px 30px rgba(8, 47, 73, 0.18);
}

.tech-brand-logo img,
.tech-footer-logo img {
    width: 32px;
    height: 32px;
    object-fit: contain;
    display: block;
}

.tech-navbar .tech-brand-logo {
    width: 58px;
    height: 58px;
    border-radius: 18px;
    box-shadow: 0 12px 28px rgba(8, 145, 178, 0.2);
}

.tech-brand-copy {
    display: flex;
    flex-direction: column;
    max-width: 92px;
    line-height: 1.25;
}

.tech-brand-copy strong {
    font-size: 15px;
    font-weight: 800;
    line-height: 1.05;
}

.tech-brand-copy small {
    color: #fff;
    font-size: 15px;
    font-weight: 800;
    line-height: 1.05;
}

.tech-search {
    flex: 1 1 560px;
    max-width: 650px;
    min-width: 260px;
    margin: 0;
}

.tech-search-control {
    position: relative;
    display: flex;
    align-items: center;
    height: 64px;
    overflow: hidden;
    border: 1px solid rgba(125, 211, 252, 0.55);
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 12px 28px rgba(8, 145, 178, 0.12);
}

.tech-search-control input {
    flex: 1;
    width: 100%;
    height: 100%;
    border: 0;
    outline: 0;
    padding: 0 120px 0 20px;
    color: #334155;
    font-size: 16px;
    font-weight: 800;
    background: transparent;
}

.tech-search-control input::placeholder {
    color: #475569;
    opacity: 1;
}

.tech-search-hint {
    position: absolute;
    left: 130px;
    top: 50%;
    color: #94a3b8;
    font-size: 16px;
    font-weight: 800;
    transform: translateY(-50%);
    pointer-events: none;
    transition: opacity 0.15s ease;
}

.tech-search-control input:focus + .tech-search-hint,
.tech-search-control input:not(:placeholder-shown) + .tech-search-hint {
    opacity: 0;
}

.tech-search-control button {
    position: absolute;
    top: 0;
    right: 0;
    display: grid;
    place-items: center;
    width: 58px;
    height: 100%;
    border: 0;
    border-left: 1px solid #bae6fd;
    color: var(--tech-blue);
    background: #ecfeff;
    font-size: 23px;
}

.tech-header-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 0 0 auto;
}

.tech-header-action {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 58px;
    padding: 0 18px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    color: #fff;
    background: rgba(14, 116, 144, 0.25);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
    transition: background 0.2s ease, transform 0.2s ease;
}

.tech-header-action:hover,
.tech-header-action:focus {
    color: #fff;
    background: rgba(14, 116, 144, 0.42);
    transform: translateY(-1px);
}

.tech-header-action span {
    display: grid;
    place-items: center;
    width: 34px;
    height: 34px;
    border-radius: 11px;
    color: #fff;
    background: rgba(255, 255, 255, 0.16);
}

.tech-header-action strong {
    white-space: nowrap;
    font-size: 14px;
    font-weight: 800;
}

.tech-header-cart em {
    position: absolute;
    top: 2px;
    right: 5px;
    display: grid;
    place-items: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    color: #fff;
    background: #ff6a00;
    font-style: normal;
    font-size: 20px;
    font-weight: 800;
    box-shadow: 0 10px 20px rgba(8, 145, 178, 0.24);
}

.tech-hero {
    padding: 38px 0 28px;
}

.tech-hero-card {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(280px, 0.92fr);
    gap: 28px;
    overflow: hidden;
    min-height: 360px;
    padding: 48px;
    border-radius: 36px;
    color: #fff;
    background:
        linear-gradient(135deg, rgba(15, 118, 110, 0.95), rgba(6, 182, 212, 0.95)),
        radial-gradient(circle at 82% 18%, rgba(255, 255, 255, 0.34), transparent 26%);
    box-shadow: var(--tech-shadow);
}

.tech-hero-card::before,
.tech-hero-card::after {
    position: absolute;
    content: "";
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.14);
}

.tech-hero-card::before {
    width: 280px;
    height: 280px;
    right: -70px;
    top: -80px;
}

.tech-hero-card::after {
    width: 160px;
    height: 160px;
    left: 45%;
    bottom: -70px;
}

.tech-hero-copy,
.tech-hero-visual {
    position: relative;
    z-index: 1;
}

.tech-eyebrow {
    display: inline-flex;
    align-items: center;
    width: max-content;
    margin-bottom: 12px;
    padding: 7px 12px;
    border-radius: 999px;
    color: #075985;
    background: #cffafe;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.tech-eyebrow-light {
    color: #ecfeff;
    background: rgba(255, 255, 255, 0.16);
}

.tech-hero h1 {
    margin: 0 0 16px;
    font-size: clamp(42px, 7vw, 86px);
    line-height: 0.92;
    font-weight: 800;
    letter-spacing: -0.06em;
}

.tech-hero p {
    max-width: 680px;
    margin: 0;
    color: rgba(255, 255, 255, 0.9);
    font-size: 17px;
    line-height: 1.7;
}

.tech-hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 26px;
}

.tech-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 46px;
    padding: 0 20px;
    border-radius: 999px;
    font-weight: 800;
