.tech-btn-light {
    color: #075985;
    background: #fff;
}

.tech-btn-outline {
    color: #fff;
    border: 1px solid rgba(255, 255, 255, 0.58);
}

.tech-hero-visual {
    display: grid;
    place-items: center;
}

