    color: #fff;
    display: grid;
    place-items: center;
    font-size: 18px;
    transition: all 0.2s ease;
}

.tech-add-cart-btn:hover {
    background: #0f766e;
    transform: scale(1.1);
}

.tech-flash-section {
    padding-top: 28px;
}

.tech-flash-shell {
    overflow: hidden;
    padding: 50px 40px;
    border-radius: 40px;
    background:
        radial-gradient(circle at 16% 0%, rgba(254, 240, 138, 0.35), transparent 28%),
        linear-gradient(135deg, #075985, #0891b2 58%, #0f766e);
    box-shadow: 0 30px 80px rgba(8, 145, 178, 0.25);
}

.tech-flash-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 24px;
    color: #fff;
}

.tech-flash-head p {
    max-width: 660px;
    margin: 10px 0 0;
    color: rgba(255, 255, 255, 0.82);
    line-height: 1.7;
}

.tech-countdown {
    display: flex;
    flex-shrink: 0;
    gap: 12px;
}

.tech-countdown span {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-width: 60px;
    color: #fff;
}

.tech-countdown strong {
    font-size: 32px;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 4px;
}

.tech-countdown small {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.7);
}

.tech-sale-viewport {
    position: relative;
}

.tech-sale-track {
    display: grid;
    grid-auto-columns: minmax(280px, 320px);
    grid-auto-flow: column;
    gap: 20px;
    overflow-x: auto;
    padding: 4px 4px 24px;
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
    cursor: grab;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
}

.tech-sale-track.is-dragging {
    cursor: grabbing;
    scroll-behavior: auto;
    scroll-snap-type: none;
    user-select: none;
}

.tech-sale-track.is-dragging a,
.tech-sale-track.is-dragging button {
    pointer-events: none;
}

.tech-sale-nav {
    position: absolute;
    top: calc(50% - 10px);
    z-index: 4;
    display: grid;
    place-items: center;
    width: 48px;
    height: 48px;
    border: 0;
    border-radius: 50%;
    color: #075985;
    background: #fff;
    box-shadow: 0 18px 38px rgba(15, 23, 42, 0.24);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.tech-sale-prev {
    left: 8px;
    transform: translate(-12px, -50%);
}

.tech-sale-next {
    right: 8px;
    transform: translate(12px, -50%);
}

.tech-sale-nav i {
    font-size: 28px;
    line-height: 1;
}

.tech-sale-viewport:hover .tech-sale-nav:not(:disabled),
.tech-sale-viewport:focus-within .tech-sale-nav:not(:disabled),
.tech-sale-viewport:hover .tech-sale-next:not(:disabled),
.tech-sale-viewport:focus-within .tech-sale-next:not(:disabled) {
    opacity: 1;
    pointer-events: auto;
    transform: translate(0, -50%);
}

.tech-sale-nav:hover,
.tech-sale-nav:focus-visible {
    box-shadow: 0 22px 48px rgba(15, 23, 42, 0.3);
}

.tech-sale-nav:disabled {
    opacity: 0 !important;
    pointer-events: none !important;
}

.tech-sale-track::-webkit-scrollbar {
    height: 8px;
}

.tech-sale-track::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.55);
}

.tech-sale-item {
    scroll-snap-align: start;
}

