:root {
    --tech-primary: #06b6d4;
    --tech-primary-dark: #0e7490;
    --tech-secondary: #0f766e;
    --tech-accent: #0284c7;
    --tech-bg: #f8fafc;
    --tech-card-bg: #ffffff;
    --tech-text: #0f172a;
    --tech-text-muted: #64748b;
    --tech-border: #e2e8f0;
    --tech-radius-lg: 32px;
    --tech-radius-md: 20px;
    --tech-shadow: 0 10px 40px rgba(0, 0, 0, 0.04);
    --tech-shadow-lg: 0 30px 60px rgba(0, 0, 0, 0.08);
    --tech-gradient: linear-gradient(135deg, #06b6d4 0%, #0891b2 50%, #0f766e 100%);
}

/* Global Polish & Scale */
body.tech-home {
    background-color: var(--tech-bg);
    color: var(--tech-text);
    font-family: 'Be Vietnam Pro', sans-serif;
    -webkit-font-smoothing: antialiased;
}

.container {
    width: 100% !important;
    max-width: 1240px !important;
    padding-left: 20px !important;
    padding-right: 20px !important;
    margin-left: auto !important;
    margin-right: auto !important;
}

.tech-section {
    padding: 40px 0;
}

.tech-section-head {
    margin-bottom: 40px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
}

.tech-section-head h2 {
    font-size: 36px;
    font-weight: 800;
    margin: 5px 0 0;
    letter-spacing: -0.5px;
}

.tech-eyebrow {
    color: var(--tech-primary);
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 2px;
    display: block;
}

/* Header Polish */
.shopw-topbar {
    background: var(--tech-gradient);
    color: white;
    padding: 10px 0;
    font-size: 13px;
    font-weight: 500;
}

.shopw-topbar-pill {
    display: flex;
    align-items: center;
    gap: 8px;
    opacity: 0.95;
}

.shopw-header {
    padding: 20px 0;
    background: white;
    display: grid !important;
    grid-template-columns: 240px 1fr 320px !important;
    align-items: center;
    gap: 40px;
    border-bottom: 1px solid var(--tech-border);
}

.shopw-logo img {
    height: 54px;
    width: auto;
}

.shopw-search-shell {
    flex: 1;
    width: 100%;
    max-width: 100% !important;
}

.shopw-search {
    position: relative;
    display: flex;
    align-items: center;
}

.shopw-search-entry {
    flex: 1;
    background: #f1f5f9;
    border-radius: 99px;
    padding: 4px 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    border: 2px solid transparent;
    transition: all 0.3s ease;
}

.shopw-search-entry:focus-within {
    background: white;
    border-color: var(--tech-primary);
    box-shadow: 0 0 0 4px rgba(6, 182, 212, 0.1);
}

.shopw-search-prefix {
    font-size: 13px;
    font-weight: 700;
    color: var(--tech-primary);
    white-space: nowrap;
}

.shopw-search-input-stage {
    flex: 1;
}

.shopw-search-entry input {
    width: 100%;
    background: transparent;
    border: none;
    height: 48px;
    font-size: 16px;
    font-weight: 500;
    outline: none !important;
}

.shopw-search-btn {
    width: 44px;
    height: 44px;
    background: var(--tech-primary);
    color: white;
    border: none;
    border-radius: 50%;
    margin-left: -48px;
    position: relative;
    z-index: 2;
    cursor: pointer;
    transition: transform 0.2s ease;
}

.shopw-search-btn:hover {
    transform: scale(1.05);
}

.shopw-utilities {
    display: flex;
    gap: 32px;
    align-items: center;
    margin: 0;
    padding: 0;
    list-style: none;
}

.shopw-util a {
    display: flex;
    align-items: center;
    gap: 12px;
    color: var(--tech-text);
    text-decoration: none;
}

.shopw-util i {
    font-size: 22px;
    color: var(--tech-primary);
}

.shopw-links li a {
    padding: 15px 20px !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    text-transform: uppercase;
}

.shopw-nav-text strong {
    font-size: 14px;
}

.shopw-nav-text small {
    font-size: 11px;
}
    background: #ef4444;
    color: white;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 99px;
    margin-left: -5px;
}

/* Hero Section Polish */
.tech-home-hero-slider .container {
    background: transparent !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin-top: 20px !important;
}

.shopw-home-hero {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 20px;
    align-items: stretch;
}

.shopw-home-hero__main {
    border-radius: var(--tech-radius-lg);
    overflow: hidden;
    box-shadow: var(--tech-shadow-lg);
    height: 500px;
}

.shopw-home-hero__image-wrapper {
    position: relative;
    height: 500px;
    overflow: hidden;
    background: #0f172a;
}

.shopw-home-hero__image-wrapper::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    background:
        linear-gradient(90deg, rgba(2, 6, 23, 0.72) 0%, rgba(15, 23, 42, 0.48) 38%, rgba(15, 23, 42, 0.06) 76%),
        linear-gradient(180deg, rgba(2, 6, 23, 0.08) 0%, rgba(2, 6, 23, 0.22) 100%);
    pointer-events: none;
}

.shopw-home-hero__image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    display: block;
}

.shopw-home-hero__caption {
    position: absolute;
    left: 60px;
    top: 50%;
    transform: translateY(-50%);
    color: white;
    max-width: 560px;
    z-index: 5;
}

.shopw-home-hero__pill {
    background: var(--tech-primary);
    padding: 6px 16px;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 800;
    margin-bottom: 16px;
    display: inline-block;
}

.shopw-home-hero__title {
    max-width: 620px;
    font-size: 46px;
    font-weight: 900;
    line-height: 1.08;
    margin: 0 0 18px;
    letter-spacing: 0;
    text-transform: none;
}

.shopw-home-hero__desc {
    max-width: 540px;
    font-size: 17px;
    line-height: 1.62;
    margin-bottom: 28px;
    opacity: 0.95;
    font-weight: 500;
}

.shopw-home-hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.btn-shopw--primary {
    background: var(--tech-primary);
    color: white;
    padding: 14px 28px;
    border: 1px solid var(--tech-primary);
    border-radius: 99px;
    font-weight: 800;
    font-size: 15px;
    text-decoration: none;
    transition: all 0.3s ease;
    box-shadow: 0 10px 30px rgba(6, 182, 212, 0.24);
}

.btn-shopw--primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 15px 34px rgba(6, 182, 212, 0.34);
    color: white;
    text-decoration: none;
}

.btn-shopw--ghost {
    align-items: center;
    display: inline-flex;
    gap: 10px;
    padding: 14px 24px;
    border: 1px solid rgba(255, 255, 255, 0.38);
    border-radius: 99px;
    background: rgba(255, 255, 255, 0.12);
    color: white;
    font-size: 15px;
    font-weight: 800;
    text-decoration: none;
    backdrop-filter: blur(8px);
    transition: all 0.3s ease;
}

.btn-shopw--ghost:hover,
.btn-shopw--ghost:focus {
    transform: translateY(-2px);
    border-color: rgba(255, 255, 255, 0.68);
    background: rgba(255, 255, 255, 0.2);
    color: white;
    text-decoration: none;
}

.tech-home-hero-slider .shopw-home-hero {
    grid-template-columns: minmax(0, 1fr) 320px !important;
    gap: 20px !important;
}

.tech-home-hero-slider .shopw-home-hero__main,
.tech-home-hero-slider .shopw-home-hero__image-wrapper {
    height: 500px !important;
}

.shopw-home-hero__aside {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.shopw-hero-util-card {
    background: white;
    color: var(--tech-text);
    padding: 30px;
    border-radius: var(--tech-radius-md);
    display: flex;
    align-items: center;
    gap: 20px;
    flex: 1;
    box-shadow: var(--tech-shadow);
    border: 1px solid var(--tech-border);
    transition: all 0.3s ease;
}

.shopw-hero-util-card:hover {
    transform: translateY(-2px);
    border-color: rgba(6, 182, 212, 0.35);
    background: linear-gradient(135deg, #ecfeff, #dffafa);
    color: #0f172a;
    box-shadow: 0 14px 30px rgba(6, 182, 212, 0.14);
}

.shopw-hero-util-card:hover .shopw-hero-util-icon {
    background: rgba(6, 182, 212, 0.14);
    color: #0891b2;
}

.shopw-hero-util-card:hover .shopw-hero-util-body span {
    color: #475569;
}

.shopw-hero-util-icon {
    width: 60px;
    height: 60px;
    background: #f0f9ff;
    border-radius: 18px;
    display: grid;
    place-items: center;
    font-size: 28px;
    color: var(--tech-primary);
}

.shopw-hero-util-body strong {
    display: block;
    font-size: 18px;
    font-weight: 800;
    margin-bottom: 4px;
}

.shopw-hero-util-body span {
    font-size: 14px;
    color: var(--tech-text-muted);
    font-weight: 500;
}

/* Policy Section Polish */
.tech-policy-card {
    background: white;
    padding: 35px 25px;
    border-radius: var(--tech-radius-md);
    box-shadow: var(--tech-shadow);
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    border: 1px solid var(--tech-border);
    transition: all 0.3s ease;
}

.tech-policy-card:hover {
    transform: translateY(-10px);
    box-shadow: var(--tech-shadow-lg);
}

.tech-policy-icon {
    width: 70px;
    height: 70px;
    background: #f0f9ff;
    color: var(--tech-primary);
    border-radius: 24px;
    display: grid;
    place-items: center;
    font-size: 32px;
    margin-bottom: 20px;
}

.tech-policy-body h3 {
    font-size: 18px;
    font-weight: 800;
    margin-bottom: 12px;
}

.tech-policy-body p {
    font-size: 14px;
    line-height: 1.5;
    color: var(--tech-text-muted);
    font-weight: 500;
}

/* Flash Sale Polish */
.tech-flash-shell {
    background: #0f172a !important;
    padding: 50px !important;
    border-radius: var(--tech-radius-lg) !important;
    color: white !important;
}

.tech-flash-head h2 {
    color: white !important;
    font-size: 42px !important;
}

.tech-countdown {
    display: flex;
    gap: 15px;
    margin-top: 20px;
}

.tech-countdown span {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    padding: 15px 20px !important;
    border-radius: 16px !important;
    min-width: 90px;
    text-align: center;
}

.tech-countdown strong {
    font-size: 32px !important;
    display: block;
    line-height: 1;
    margin-bottom: 5px;
}

.tech-countdown small {
    font-size: 12px !important;
    text-transform: uppercase;
    font-weight: 700;
    opacity: 0.7;
}

.tech-sale-viewport {
    margin-top: 50px;
}

.tech-sale-item {
    min-width: 320px !important;
}

/* Product Card Scale */
.tech-product-card {
    min-height: 100%;
    padding: 0 !important;
    overflow: hidden;
}

.tech-product-media {
    display: grid;
    place-items: center;
    flex: 0 0 220px;
    height: 220px;
    min-height: 220px;
    margin-bottom: 0;
    padding: 24px 22px 16px;
}

.tech-product-media img {
    display: block;
    width: 100%;
    max-width: 100%;
    height: 172px;
    max-height: 172px;
    object-fit: contain;
    transition: transform 0.3s ease;
}

.tech-product-card:hover .tech-product-media img {
    transform: scale(1.05);
}

.tech-product-body {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    padding: 18px;
}

.tech-product-body h3 {
    display: -webkit-box;
    min-height: 44px;
    max-height: 44px;
    margin: 0 0 12px;
    overflow: hidden;
    color: #0f172a;
    font-size: 15px;
    font-weight: 800;
    line-height: 1.45;
    text-shadow: none;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.tech-product-card-compact .tech-product-body h3 {
    min-height: 42px;
    max-height: 42px;
    font-size: 14px;
}

.tech-product-card-compact .tech-product-media {
    flex-basis: 190px;
    height: 190px;
    min-height: 190px;
    padding: 22px 18px 14px;
}

.tech-product-card-compact .tech-product-media img {
    height: 148px;
    max-height: 148px;
}

.tech-product-body h3 a,
.tech-product-body h3 a:visited,
.tech-product-card .tech-product-body h3 a {
    color: #0f172a !important;
    opacity: 1;
    text-decoration: none;
    text-shadow: none;
}

.tech-product-card:hover .tech-product-body h3,
.tech-product-card:focus-within .tech-product-body h3,
.tech-product-card:hover .tech-product-body h3 a,
.tech-product-card:focus-within .tech-product-body h3 a,
.tech-product-body h3 a:hover,
.tech-product-body h3 a:focus-visible {
    color: #0284c7 !important;
    opacity: 1;
    text-decoration: none;
    text-shadow: none;
}

.tech-product-rating {
    min-height: 18px;
}

.tech-product-footer {
    min-height: 58px;
}

.tech-sale-item {
    display: flex;
    align-self: stretch;
}

.tech-sale-item .tech-product-card {
    height: 100%;
}

.tech-product-grid > [class*="col-"] {
    align-items: stretch;
}

/* Categories Polish */
.tech-categories-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: 20px;
}

.tech-cat-card {
    background: white;
    padding: 30px 15px;
    border-radius: var(--tech-radius-md);
    text-align: center;
    text-decoration: none;
    color: var(--tech-text);
    box-shadow: var(--tech-shadow);
    border: 1px solid var(--tech-border);
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
}

.tech-cat-card:hover {
    transform: translateY(-5px);
    border-color: var(--tech-primary);
    box-shadow: var(--tech-shadow-lg);
}

.tech-cat-icon {
    width: 60px;
    height: 60px;
    background: #f8fafc;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-size: 24px;
    color: var(--tech-primary);
    transition: all 0.3s ease;
}

.tech-cat-card:hover .tech-cat-icon {
    background: var(--tech-primary);
    color: white;
}

.tech-cat-card strong {
    font-size: 14px;
    font-weight: 700;
}

/* Promo Banners Polish */
.tech-promo-grid {
    display: flex;
    gap: 24px;
}

.tech-promo-card {
    position: relative;
    height: 240px;
    border-radius: var(--tech-radius-md);
    overflow: hidden;
    text-decoration: none;
    color: white;
    display: block;
    box-shadow: var(--tech-shadow);
}

.tech-promo-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.tech-promo-card:hover img {
    transform: scale(1.05);
}

.tech-promo-content {
    position: absolute;
    inset: 0;
    padding: 30px;
    background: linear-gradient(90deg, rgba(15, 23, 42, 0.8) 0%, rgba(15, 23, 42, 0) 60%);
    display: flex;
    flex-direction: column;
    justify-content: center;
    z-index: 2;
}

.tech-promo-eyebrow {
    font-size: 12px;
    font-weight: 800;
    color: var(--tech-primary);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
}

.tech-promo-card h3 {
    font-size: 24px;
    font-weight: 800;
    margin: 0 0 5px;
    color: white;
}

.tech-promo-card p {
    font-size: 14px;
    opacity: 0.8;
    margin-bottom: 20px;
}

.tech-promo-btn {
    font-size: 13px;
    font-weight: 700;
    display: flex;
    align-items: center;
    gap: 8px;
}

/* Category Promo Banner Grid */
.tech-promo-banners-section .tech-promo-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 24px;
    margin: 0;
}

.tech-promo-banners-section .tech-promo-grid > [class*="col-"] {
    float: none;
    width: auto;
    max-width: none;
    min-width: 0;
    padding: 0;
}

.tech-promo-banners-section .tech-promo-card {
    display: block;
    width: 100%;
    height: 188px;
    margin: 0;
    border-radius: var(--tech-radius-md);
}

.tech-promo-banners-section .tech-promo-card:hover {
    transform: translateY(-3px);
}

.tech-promo-banners-section .tech-promo-content {
    padding: 24px;
}

.tech-promo-banners-section .tech-promo-card h3 {
    display: -webkit-box;
    max-width: 72%;
    overflow: hidden;
    line-height: 1.2;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.tech-promo-banners-section .tech-promo-card p {
    max-width: 72%;
}

.tech-promo-banners-section .tech-promo-card img {
    object-fit: cover;
}

/* Product Grid Scale */
.tech-product-grid {
    margin: 0 -12px;
}

.tech-product-grid [class*="col-"] {
    padding: 12px;
}

/* News Section Polish */
.tech-news-card {
    background: white;
    border-radius: var(--tech-radius-md);
    overflow: hidden;
    box-shadow: var(--tech-shadow);
    border: 1px solid var(--tech-border);
    height: 100%;
    display: flex;
    flex-direction: column;
    text-decoration: none;
    color: var(--tech-text);
}

.tech-news-thumb {
    height: 260px;
    overflow: hidden;
}

.tech-news-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.tech-news-card:hover .tech-news-thumb img {
    transform: scale(1.05);
}

.tech-news-body {
    padding: 25px;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.tech-news-meta {
    font-size: 12px;
    color: var(--tech-text-muted);
    font-weight: 600;
    margin-bottom: 10px;
    display: flex;
    gap: 15px;
}

.tech-news-body h3 {
    font-size: 18px;
    font-weight: 800;
    margin: 0 0 12px;
    line-height: 1.5;
}

.tech-news-body p {
    font-size: 14px;
    color: var(--tech-text-muted);
    line-height: 1.6;
    margin-bottom: 20px;
}

.tech-news-link {
    margin-top: auto;
    font-size: 14px;
    font-weight: 700;
    color: var(--tech-primary);
}

/* Partners Polish */
.tech-partners-shell {
    background: white;
    padding: 60px;
    border-radius: var(--tech-radius-lg);
    box-shadow: var(--tech-shadow);
}

.tech-partner-logo {
    display: grid;
    place-items: center;
    width: 160px;
    height: 80px;
    padding: 14px 18px;
    border: 1px solid var(--tech-border);
    border-radius: 18px;
    background: #fff;
    filter: none;
    opacity: 1;
}

.tech-partner-logo:hover {
    transform: translateY(-3px);
    box-shadow: var(--tech-shadow);
}

.tech-partner-logo img {
    display: block;
    max-width: 118px;
    max-height: 42px;
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.shopw-home-hero__caption {
    text-shadow: 0 8px 24px rgba(15, 23, 42, 0.42);
}

/* Footer Polish */
.tech-footer {
    background: #0f172a;
    color: white;
    padding: 42px 0 0;
}

.shopw-footer-shell {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 15px;
}

.shopw-footer-main {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr 1.2fr 1fr;
    gap: 28px;
    padding-bottom: 24px;
}

.tech-footer h3 {
    color: white;
    font-size: 18px;
    font-weight: 800;
    margin-bottom: 14px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.tech-footer-brand img {
    height: 56px;
    margin-bottom: 14px;
}

.tech-footer-brand-description {
    font-size: 15px;
    line-height: 1.6;
    opacity: 0.7;
    margin-bottom: 14px;
}

.tech-footer-nav a {
    color: white;
    opacity: 0.7;
    text-decoration: none;
    display: block;
    margin-bottom: 10px;
    font-size: 15px;
    transition: all 0.3s ease;
}

.tech-footer-nav a:hover {
    opacity: 1;
    transform: translateX(5px);
    color: var(--tech-primary);
}

.tech-footer-bottom {
    margin-top: 16px;
    padding: 16px 0 18px;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.tech-footer-bottom-flex {
    display: flex;
    justify-content: space-between;
    align-items: center;
    opacity: 0.6;
    font-size: 14px;
    gap: 12px;
}

/* Responsive Fixes */
@media (max-width: 992px) {
    .container {
        width: 100% !important;
    }
    
    .shopw-home-hero {
        grid-template-columns: 1fr;
    }

    .tech-home-hero-slider .shopw-home-hero {
        grid-template-columns: minmax(0, 1fr) !important;
    }

    .shopw-home-hero__main,
    .shopw-home-hero__image-wrapper {
        height: 420px;
    }

    .tech-home-hero-slider .shopw-home-hero__main,
    .tech-home-hero-slider .shopw-home-hero__image-wrapper {
        height: 420px !important;
    }

    .shopw-home-hero__aside {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    
    .tech-promo-grid {
        flex-direction: column;
    }

    .tech-promo-banners-section .tech-promo-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 20px;
    }

    .tech-promo-banners-section .tech-promo-card {
        height: 176px;
    }
}

@media (max-width: 768px) {
    .tech-section {
        padding: 60px 0;
    }
    
    .shopw-header {
        flex-direction: column;
        gap: 20px;
    }
    
    .shopw-home-hero__caption {
        left: 24px;
        right: 24px;
        max-width: none;
    }
    
    .shopw-home-hero__title {
        font-size: 30px;
        line-height: 1.14;
    }

    .shopw-home-hero__desc {
        font-size: 15px;
        line-height: 1.55;
        margin-bottom: 20px;
    }

    .shopw-home-hero__main,
    .shopw-home-hero__image-wrapper {
        height: 390px;
    }

    .tech-home-hero-slider .shopw-home-hero__main,
    .tech-home-hero-slider .shopw-home-hero__image-wrapper {
        height: 390px !important;
    }

    .shopw-home-hero__actions {
        gap: 10px;
    }

    .btn-shopw--primary,
    .btn-shopw--ghost {
        padding: 11px 16px;
        font-size: 13px;
    }

    .shopw-home-hero__aside {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .shopw-hero-util-card {
        padding: 18px;
    }

    .tech-promo-banners-section .tech-promo-grid {
        grid-template-columns: minmax(0, 1fr);
        gap: 16px;
    }

    .tech-promo-banners-section .tech-promo-card {
        height: 168px;
    }

    .tech-promo-banners-section .tech-promo-content {
        padding: 20px;
    }
}

