/* ============================================================
   Cart V2 — full page redesign (matches design mock 100%)
   ============================================================ */

.cart-v2-page {
    background: #f3f6f9;
}

.cart-v2 {
    padding: 24px 0 56px;
}

.cart-v2-container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 20px;
}

.cart-v2-breadcrumb {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    color: #64748b;
    margin-bottom: 16px;
}
.cart-v2-breadcrumb a {
    color: #64748b;
    text-decoration: none;
    transition: color .2s;
}
.cart-v2-breadcrumb a:hover { color: var(--tech-primary); }
.cart-v2-breadcrumb-sep { color: #cbd5e1; }
.cart-v2-breadcrumb strong {
    color: var(--tech-primary);
    font-weight: 600;
}

.cart-v2-flash {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    border-radius: 10px;
    margin-bottom: 16px;
    font-size: 14px;
}
.cart-v2-flash--success { background: #ecfdf5; color: #047857; border: 1px solid #6ee7b7; }
.cart-v2-flash--error { background: #fef2f2; color: #b91c1c; border: 1px solid #fca5a5; }
.cart-v2-flash i { font-size: 16px; }

/* Page head */
.cart-v2-pagehead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 20px;
}
.cart-v2-title {
    margin: 0;
    font-size: 22px;
    font-weight: 700;
    color: #0f172a;
    text-transform: uppercase;
    letter-spacing: .02em;
}
.cart-v2-title-meta {
    font-size: 14px;
    font-weight: 500;
    color: #64748b;
    text-transform: none;
    letter-spacing: 0;
    margin-left: 4px;
}
.cart-v2-back {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--tech-primary);
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
}
.cart-v2-back:hover { color: var(--tech-primary-dark); }
.cart-v2-back i { font-size: 14px; }

/* Empty state */
.cart-v2-empty {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    padding: 56px 24px;
    text-align: center;
}
.cart-v2-empty-icon {
    width: 84px;
    height: 84px;
    margin: 0 auto 18px;
    background: #ecfeff;
    color: var(--tech-primary);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 34px;
}
.cart-v2-empty h2 {
    margin: 0 0 8px;
    font-size: 20px;
    color: #0f172a;
}
.cart-v2-empty p {
    margin: 0 auto 24px;
    color: #64748b;
    max-width: 480px;
}
.cart-v2-empty-actions {
    display: flex;
    gap: 12px;
    justify-content: center;
    flex-wrap: wrap;
}

/* Grid */
.cart-v2-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 380px;
    gap: 20px;
    align-items: start;
}

.cart-v2-card {
    background: #fff;
    border: 1px solid #e6ebf2;
    border-radius: 14px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}

/* ===== Cart list ===== */
.cart-v2-list { padding: 0; overflow: hidden; }

.cart-v2-list-head,
.cart-v2-row {
    display: grid;
    grid-template-columns: 32px minmax(0, 1fr) 140px 130px 130px 56px;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
}

.cart-v2-list-head {
    background: #f8fafc;
    border-bottom: 1px solid #e6ebf2;
    color: #475569;
    font-size: 13px;
    font-weight: 600;
}
.cart-v2-col { min-width: 0; }
.cart-v2-col-product { padding-left: 4px; }
.cart-v2-col-price,
.cart-v2-col-total { text-align: right; }
.cart-v2-col-qty,
.cart-v2-col-action { text-align: center; }

.cart-v2-list-body { padding: 0; }
.cart-v2-row {
    border-bottom: 1px solid #eef2f7;
    background: #fff;
    transition: background .15s;
}
.cart-v2-row:last-child { border-bottom: 0; }
.cart-v2-row:hover { background: #fafcfd; }

/* Checkbox */
.cart-v2-check {
    position: relative;
    display: inline-flex;
    align-items: center;
    cursor: pointer;
    user-select: none;
}
.cart-v2-check input {
    position: absolute;
    opacity: 0;
    inset: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
    margin: 0;
}
.cart-v2-check-box {
    width: 18px;
    height: 18px;
    border: 1.5px solid #cbd5e1;
    border-radius: 4px;
    background: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: all .15s;
}
.cart-v2-check input:checked + .cart-v2-check-box {
    background: var(--tech-primary);
    border-color: var(--tech-primary);
}
.cart-v2-check-box::after {
    content: "";
    width: 10px;
    height: 6px;
    border-left: 2px solid #fff;
    border-bottom: 2px solid #fff;
    transform: rotate(-45deg) translate(1px, -1px);
    opacity: 0;
    transition: opacity .15s;
}
.cart-v2-check input:checked + .cart-v2-check-box::after { opacity: 1; }
.cart-v2-check--inline { gap: 8px; }
.cart-v2-check-label { font-size: 14px; color: #0f172a; font-weight: 500; }

/* Product cell */
.cart-v2-product {
    display: flex;
    gap: 14px;
    align-items: center;
    min-width: 0;
}
.cart-v2-thumb {
    flex: 0 0 auto;
    width: 72px;
    height: 72px;
    border-radius: 10px;
    border: 1px solid #eef2f7;
    background: #fff;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4px;
}
.cart-v2-thumb img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}
.cart-v2-product-info { min-width: 0; }
.cart-v2-product-name {
    margin: 0;
    font-size: 14px;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}
.cart-v2-product-variant {
    margin: 6px 0 0;
    font-size: 12px;
    color: #475569;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}
.cart-v2-variant-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #1f2937;
    border: 1px solid rgba(15,23,42,.15);
    display: inline-block;
}
.cart-v2-product-stock {
    margin: 6px 0 0;
    font-size: 12px;
    color: var(--tech-primary);
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.cart-v2-product-stock i { font-size: 11px; }

/* Price cell */
.cart-v2-price {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 2px;
    line-height: 1.2;
}
.cart-v2-price-current {
    font-size: 15px;
    font-weight: 700;
    color: #0f172a;
}
.cart-v2-price-old {
    font-size: 12px;
    color: #94a3b8;
    text-decoration: line-through;
}
.cart-v2-price-pct {
    display: inline-block;
    margin-top: 2px;
    padding: 2px 6px;
    background: #fee2e2;
    color: #dc2626;
    font-size: 11px;
    font-weight: 700;
    border-radius: 4px;
}

/* Stepper */
.cart-v2-stepper {
    display: inline-flex;
    align-items: center;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}
.cart-v2-stepper-btn {
    width: 30px;
    height: 32px;
    border: 0;
    background: #fff;
    color: #475569;
    font-size: 12px;
    cursor: pointer;
    transition: all .15s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
.cart-v2-stepper-btn:hover {
    background: #ecfeff;
    color: var(--tech-primary);
}
.cart-v2-stepper-input {
    width: 40px;
    height: 32px;
    border: 0;
    border-left: 1px solid #e2e8f0;
    border-right: 1px solid #e2e8f0;
    text-align: center;
    font-size: 14px;
    font-weight: 600;
    color: #0f172a;
    -moz-appearance: textfield;
    background: #fff;
}
.cart-v2-stepper-input::-webkit-outer-spin-button,
.cart-v2-stepper-input::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
}
.cart-v2-stepper-input:focus { outline: 0; }

/* Line total */
.cart-v2-line-total {
    font-size: 15px;
    font-weight: 700;
    color: #ef4444;
}

/* Remove button */
.cart-v2-row-remove {
    width: 34px;
    height: 34px;
    margin: 0 auto;
    border: 0;
    background: transparent;
    color: #94a3b8;
    border-radius: 8px;
    cursor: pointer;
    transition: all .15s;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
}
.cart-v2-row-remove:hover { background: #fef2f2; color: #dc2626; }

/* List footer */
.cart-v2-list-foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    padding: 14px 18px;
    background: #f8fafc;
    border-top: 1px solid #e6ebf2;
}
.cart-v2-list-foot-left {
    display: flex;
    align-items: center;
    gap: 18px;
    flex-wrap: wrap;
}
.cart-v2-link-danger {
    background: 0;
    border: 0;
    color: #475569;
    font-size: 14px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0;
    transition: color .15s;
}
.cart-v2-link-danger:hover { color: #dc2626; }

/* ===== Buttons ===== */
.cart-v2-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 18px;
    height: 42px;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    text-decoration: none;
    transition: all .15s;
    border: 1px solid transparent;
    box-sizing: border-box;
}
.cart-v2-btn--primary {
    background: var(--tech-primary);
    color: #fff;
}
.cart-v2-btn--primary:hover {
    background: var(--tech-primary-dark);
    color: #fff;
}
.cart-v2-btn--ghost {
    background: #fff;
    color: #475569;
    border-color: #e2e8f0;
}
.cart-v2-btn--ghost:hover {
    border-color: var(--tech-primary);
    color: var(--tech-primary);
}
.cart-v2-btn--checkout {
    width: 100%;
    background: var(--tech-primary);
    color: #fff;
    height: 46px;
    font-size: 15px;
    box-shadow: 0 4px 12px rgba(6, 182, 212, .25);
}
.cart-v2-btn--checkout:hover {
    background: var(--tech-primary-dark);
    color: #fff;
    box-shadow: 0 6px 18px rgba(6, 182, 212, .3);
}
.cart-v2-btn--quick {
    width: 100%;
    background: #fff;
    color: var(--tech-primary);
    border-color: var(--tech-primary);
    height: 46px;
    font-size: 15px;
}
.cart-v2-btn--quick:hover {
    background: #ecfeff;
    color: var(--tech-primary-dark);
    border-color: var(--tech-primary-dark);
}

/* ===== Sidebar summary ===== */
.cart-v2-aside { position: sticky; top: 16px; }
.cart-v2-summary { padding: 20px; }
.cart-v2-summary-title {
    margin: 0 0 16px;
    font-size: 15px;
    font-weight: 700;
    color: #0f172a;
    text-transform: uppercase;
    letter-spacing: .02em;
}
.cart-v2-summary-rows {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding-bottom: 16px;
    border-bottom: 1px dashed #e2e8f0;
}
.cart-v2-summary-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
}
.cart-v2-summary-row span {
    color: #64748b;
    font-size: 14px;
}
.cart-v2-summary-row strong {
    color: #0f172a;
    font-size: 15px;
    font-weight: 600;
    text-align: right;
}
.cart-v2-summary-row strong.is-discount { color: #ef4444; }
.cart-v2-summary-row strong.is-free { color: var(--tech-primary); }

/* Coupon */
.cart-v2-coupon {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.cart-v2-coupon-label {
    font-size: 14px;
    color: #475569;
    font-weight: 500;
}
.cart-v2-coupon-form {
    display: flex;
    gap: 8px;
}
.cart-v2-coupon-input {
    flex: 1;
    height: 40px;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 0 12px;
    font-size: 14px;
    color: #0f172a;
    min-width: 0;
}
.cart-v2-coupon-input:focus {
    outline: 0;
    border-color: var(--tech-primary);
    box-shadow: 0 0 0 3px rgba(6, 182, 212, .12);
}
.cart-v2-coupon-input::placeholder { color: #94a3b8; }
.cart-v2-coupon-btn {
    height: 40px;
    padding: 0 18px;
    background: var(--tech-primary);
    color: #fff;
    border: 0;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
}
.cart-v2-coupon-btn:hover { background: var(--tech-primary-dark); }
.cart-v2-coupon-active {
    margin-top: 6px;
    padding: 8px 12px;
    background: #ecfdf5;
    border: 1px solid #a7f3d0;
    border-radius: 8px;
    font-size: 13px;
    color: #047857;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}
.cart-v2-coupon-remove {
    color: #dc2626;
    text-decoration: none;
    font-size: 12px;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.cart-v2-coupon-remove:hover { text-decoration: underline; }

/* Total */
.cart-v2-summary-total {
    padding: 14px 0 16px;
    border-bottom: 1px solid #e6ebf2;
    margin-bottom: 16px;
}
.cart-v2-summary-total-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
}
.cart-v2-summary-total-row span {
    font-size: 15px;
    font-weight: 600;
    color: #0f172a;
}
.cart-v2-summary-total-row strong {
    font-size: 22px;
    font-weight: 800;
    color: #ef4444;
    line-height: 1;
}
.cart-v2-summary-vat {
    margin: 4px 0 0;
    text-align: right;
    color: #94a3b8;
    font-size: 12px;
}

/* Summary actions */
.cart-v2-summary-actions {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 14px;
}

/* Payments row */
.cart-v2-payments {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    padding: 12px 0;
    border-bottom: 1px solid #f1f5f9;
    margin-bottom: 14px;
}
.cart-v2-pay {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 22px;
    padding: 0 6px;
    color: #475569;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .02em;
}
.cart-v2-pay i { font-size: 26px; line-height: 1; }
.cart-v2-pay--visa i { color: #1a1f71; }
.cart-v2-pay--mc i { color: #eb001b; }
.cart-v2-pay--momo {
    background: #ae2070;
    color: #fff;
    border-radius: 5px;
    height: 22px;
    padding: 0 8px;
    text-transform: lowercase;
}
.cart-v2-pay--zalo {
    background: #0068ff;
    color: #fff;
