/* =====================================================================
   Category page redesign — pixel-aligned to mockup
   Scope: body.g-category .cat-x__*  (avoids legacy .shopw-category-* rules)
   ===================================================================== */

body.g-category {
    background: #f4f6f8;
    color: #0f172a;
    font-family: 'Be Vietnam Pro', system-ui, -apple-system, 'Segoe UI', sans-serif;
}

.cat-x {
    padding: 18px 0 56px;
}

.cat-x .cat-x__container {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 16px;
}

/* ---------- Breadcrumb ---------- */
.cat-x__breadcrumb {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    font-size: 13px;
    color: #64748b;
    margin-bottom: 14px;
}
.cat-x__breadcrumb a {
    color: #64748b;
    text-decoration: none;
}
.cat-x__breadcrumb a:hover { color: #0d9488; }
.cat-x__breadcrumb .sep { color: #cbd5e1; }
.cat-x__breadcrumb .current { color: #0f172a; font-weight: 500; }

/* ---------- Hero title block ---------- */
.cat-x__title-block {
    margin-bottom: 18px;
}
.cat-x__title-block h1 {
    font-size: 30px;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 6px;
    line-height: 1.2;
}
.cat-x__title-block p {
    color: #64748b;
    font-size: 14px;
    margin: 0;
}

/* ---------- Category chips (horizontal scroll) ---------- */
.cat-x__chips-wrap {
    position: relative;
    margin-bottom: 18px;
}
.cat-x__chips {
    display: flex;
    gap: 12px;
    overflow-x: auto;
    scroll-behavior: smooth;
    padding-right: 50px;
    scrollbar-width: none;
}
.cat-x__chips::-webkit-scrollbar { display: none; }

.cat-x__chip {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 12px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    padding: 12px 18px 12px 12px;
    min-width: 175px;
    text-decoration: none;
    color: #0f172a;
    transition: all .2s ease;
}
.cat-x__chip:hover {
    border-color: #0d9488;
    box-shadow: 0 6px 18px -10px rgba(13, 148, 136, .35);
    transform: translateY(-1px);
}
.cat-x__chip.is-active {
    border-color: #0d9488;
    box-shadow: 0 0 0 1px #0d9488 inset, 0 8px 22px -12px rgba(13, 148, 136, .4);
}
.cat-x__chip-icon {
    flex: 0 0 44px;
    height: 44px;
    border-radius: 10px;
    background: #ecfeff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #0d9488;
    font-size: 20px;
}
.cat-x__chip.is-active .cat-x__chip-icon { background: #ccfbf1; }
.cat-x__chip-text {
    display: flex;
    flex-direction: column;
    line-height: 1.2;
}
.cat-x__chip-text strong {
    font-size: 14px;
    font-weight: 600;
    color: #0f172a;
}
.cat-x__chip-text span {
    font-size: 12px;
    color: #94a3b8;
    margin-top: 3px;
}

.cat-x__chips-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 38px;
    height: 38px;
    border-radius: 50%;
    border: 1px solid #e2e8f0;
    background: #ffffff;
    color: #0f172a;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 16px -10px rgba(15, 23, 42, .15);
    z-index: 2;
}
.cat-x__chips-nav.is-prev { left: -10px; }
.cat-x__chips-nav.is-next { right: -10px; }
.cat-x__chips-nav:disabled { opacity: 0; pointer-events: none; }

/* ---------- Promo banner ---------- */
.cat-x__promo {
    position: relative;
    border-radius: 16px;
    background: linear-gradient(120deg, #0b3b4f 0%, #0f5c75 45%, #094f64 100%);
    color: #fff;
    overflow: hidden;
    margin-bottom: 22px;
    padding: 22px 28px;
    display: flex;
    align-items: center;
    gap: 24px;
    min-height: 110px;
}
.cat-x__promo-copy {
    display: flex;
    flex-direction: column;
    gap: 6px;
    z-index: 2;
    flex: 1;
}
.cat-x__promo-copy h3 {
    font-size: 22px;
    font-weight: 700;
    margin: 0;
    letter-spacing: .3px;
}
.cat-x__promo-copy p {
    font-size: 13px;
    color: #cbe4ec;
    margin: 0;
}
.cat-x__promo-cta {
    display: inline-flex;
    align-items: center;
    background: #0d9488;
    color: #fff;
    text-decoration: none;
    padding: 9px 20px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 13px;
    margin-top: 6px;
    align-self: flex-start;
    transition: background .2s;
}
.cat-x__promo-cta:hover { background: #0f766e; color: #fff; }

.cat-x__promo-zero {
    font-size: 76px;
    font-weight: 800;
    color: #ffffff;
    line-height: 1;
    text-shadow: 0 4px 18px rgba(0, 0, 0, .25);
    z-index: 2;
    padding-right: 4px;
}
.cat-x__promo-warranty {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: rgba(255, 255, 255, .12);
    border: 1px solid rgba(255, 255, 255, .25);
    color: #fff;
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.25;
    z-index: 2;
}
.cat-x__promo-warranty i {
    font-size: 22px;
    color: #5eead4;
}
.cat-x__promo::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
        radial-gradient(circle at 70% 50%, rgba(94, 234, 212, .12) 0%, transparent 55%),
        radial-gradient(circle at 90% 0%, rgba(255, 255, 255, .08) 0%, transparent 35%);
    pointer-events: none;
}

/* ---------- Layout: sidebar + main ---------- */
.cat-x__layout {
    display: grid;
    grid-template-columns: 256px 1fr;
    gap: 22px;
    align-items: start;
}

.cat-x__layout--full {
    grid-template-columns: 1fr;
}

/* ---------- Sidebar ---------- */
.cat-x__sidebar { display: flex; flex-direction: column; gap: 14px; }

.cat-x__panel {
    background: #ffffff;
    border-radius: 12px;
    padding: 16px 16px 18px;
    box-shadow: 0 1px 0 rgba(15, 23, 42, .04);
}
.cat-x__panel + .cat-x__panel { margin-top: 0; }
.cat-x__panel h4 {
    font-size: 14px;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 12px;
}

/* sidebar list item */
.cat-x__filter-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 9px;
}
.cat-x__filter-list li { line-height: 1; }
.cat-x__filter-item {
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    color: #475569;
    font-size: 13px;
    padding: 4px 0;
    cursor: pointer;
}
.cat-x__filter-item:hover { color: #0d9488; }
.cat-x__filter-item .ck {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1.5px solid #cbd5e1;
    flex: 0 0 16px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    color: #fff;
    background: #fff;
    transition: all .15s;
}
.cat-x__filter-item.is-active .ck,
.cat-x__filter-item input:checked + .ck {
    border-color: #0d9488;
    background: #0d9488;
}
.cat-x__filter-item.is-active .ck::before,
.cat-x__filter-item input:checked + .ck::before {
    content: "\f00c";
    font-family: FontAwesome;
}
.cat-x__filter-item .lb { flex: 1; }
.cat-x__filter-item.is-active .lb { color: #0f172a; font-weight: 500; }
.cat-x__filter-item .cnt { color: #94a3b8; font-size: 12px; font-variant-numeric: tabular-nums; }

.cat-x__filter-radio .rd {
    width: 16px; height: 16px;
    border-radius: 50%;
    border: 1.5px solid #cbd5e1;
    background: #fff;
    flex: 0 0 16px;
    position: relative;
    transition: all .15s;
}
.cat-x__filter-radio.is-active .rd,
.cat-x__filter-radio input:checked + .rd {
    border-color: #0d9488;
}
.cat-x__filter-radio.is-active .rd::after,
.cat-x__filter-radio input:checked + .rd::after {
    content: "";
    position: absolute;
    inset: 3px;
    border-radius: 50%;
    background: #0d9488;
}

.cat-x__filter-list .cat-x__see-more {
    border: 0;
    padding: 0;
    background: transparent;
    color: #0d9488;
    font-size: 13px;
    font-weight: 500;
    text-decoration: none;
    margin-top: 4px;
    display: inline-block;
    cursor: pointer;
}

/* price slider */
.cat-x__price-range {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: #94a3b8;
    margin-bottom: 10px;
}
.cat-x__price-range strong {
    color: #0f172a;
    font-weight: 500;
}
.cat-x__slider {
    height: 4px;
    background: #e2e8f0;
    border-radius: 999px;
    margin: 18px 4px 8px;
    border: 0;
}
.cat-x__slider .ui-slider-range {
    background: #0d9488;
    border-radius: 999px;
}
.cat-x__slider .ui-slider-handle {
    width: 16px; height: 16px;
    background: #fff;
    border: 2.5px solid #0d9488;
    border-radius: 50%;
    top: -7px;
    margin-left: -8px;
    cursor: grab;
    box-shadow: 0 2px 6px rgba(13, 148, 136, .25);
}
.cat-x__slider .ui-slider-handle:focus { outline: 0; }

.cat-x__price-ticks {
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    color: #94a3b8;
    margin-bottom: 14px;
}

.cat-x__price-buckets {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
}
.cat-x__price-bucket {
    text-align: center;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    color: #475569;
    border-radius: 8px;
    padding: 7px 6px;
    font-size: 12px;
    text-decoration: none;
